#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct WifiHtPhaseRing {
    records: [WifiHtPhaseRecord; WIFI_HT_PHASE_RECORD_CAPACITY],
    next: usize,
    count: u8,
}

impl WifiHtPhaseRing {
    const fn new() -> Self {
        Self {
            records: [WifiHtPhaseRecord::EMPTY; WIFI_HT_PHASE_RECORD_CAPACITY],
            next: 0,
            count: 0,
        }
    }

    fn push(&mut self, record: WifiHtPhaseRecord) {
        self.records[self.next] = record;
        self.next = (self.next + 1) % WIFI_HT_PHASE_RECORD_CAPACITY;
        if usize::from(self.count) < WIFI_HT_PHASE_RECORD_CAPACITY {
            self.count += 1;
        }
    }

    fn ordered(&self) -> ([WifiHtPhaseRecord; WIFI_HT_PHASE_RECORD_CAPACITY], u8) {
        let mut ordered = [WifiHtPhaseRecord::EMPTY; WIFI_HT_PHASE_RECORD_CAPACITY];
        let count = usize::from(self.count);
        let start = if count == WIFI_HT_PHASE_RECORD_CAPACITY {
            self.next
        } else {
            0
        };
        let mut index = 0;
        while index < count {
            ordered[index] = self.records[(start + index) % WIFI_HT_PHASE_RECORD_CAPACITY];
            index += 1;
        }
        (ordered, self.count)
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct WifiBoundedPhaseRing {
    records: [WifiBoundedPhaseRecord; WIFI_BOUNDED_PHASE_RECORD_CAPACITY],
    next: usize,
    count: u8,
}

impl WifiBoundedPhaseRing {
    const fn new() -> Self {
        Self {
            records: [WifiBoundedPhaseRecord::EMPTY; WIFI_BOUNDED_PHASE_RECORD_CAPACITY],
            next: 0,
            count: 0,
        }
    }

    fn push(&mut self, record: WifiBoundedPhaseRecord) {
        self.records[self.next] = record;
        self.next = (self.next + 1) % WIFI_BOUNDED_PHASE_RECORD_CAPACITY;
        if usize::from(self.count) < WIFI_BOUNDED_PHASE_RECORD_CAPACITY {
            self.count += 1;
        }
    }

    fn ordered(
        &self,
    ) -> (
        [WifiBoundedPhaseRecord; WIFI_BOUNDED_PHASE_RECORD_CAPACITY],
        u8,
    ) {
        let mut ordered = [WifiBoundedPhaseRecord::EMPTY; WIFI_BOUNDED_PHASE_RECORD_CAPACITY];
        let count = usize::from(self.count);
        let start = if count == WIFI_BOUNDED_PHASE_RECORD_CAPACITY {
            self.next
        } else {
            0
        };
        let mut index = 0;
        while index < count {
            ordered[index] = self.records[(start + index) % WIFI_BOUNDED_PHASE_RECORD_CAPACITY];
            index += 1;
        }
        (ordered, self.count)
    }
}

#[derive(Clone, Copy)]
struct MappedRegs {
    paddr: usize,
    vaddr: usize,
}

impl MappedRegs {
    fn from_frame(frame: &DeviceFrame) -> Self {
        Self {
            paddr: frame.paddr(),
            vaddr: frame.ptr().as_ptr() as usize,
        }
    }

    fn paddr(self) -> usize {
        self.paddr
    }

    fn vaddr(self) -> usize {
        self.vaddr
    }
}

fn cloned_pinned_regs(pinned: &Mutex<Option<MappedRegs>>) -> Option<MappedRegs> {
    pinned.lock().as_ref().copied()
}

fn cached_sdio_irq_binding() -> Option<KernelIrqBinding> {
    SDIO_IRQ_BINDING.lock().as_ref().copied()
}

fn remember_sdio_irq_binding(binding: KernelIrqBinding) {
    *SDIO_IRQ_BINDING.lock() = Some(binding);
}

pub(crate) fn pinned_mailbox_regs() -> Option<(usize, usize)> {
    cloned_pinned_regs(&PINNED_MAILBOX_REGS).map(|regs| (regs.paddr(), regs.vaddr()))
}

fn pinned_mailbox_request_page<H>(
    hal: &mut H,
    slot: &Mutex<Option<MappedRegs>>,
    reuse_action: &str,
    alloc_action: &str,
) -> Result<MappedRegs, HalError>
where
    H: DeviceHal<Error = HalError>,
{
    let mut shared_request = slot.lock();
    if let Some(frame) = shared_request.as_ref() {
        emit_breadcrumb(format_args!(
            "[pi4-wifi] mailbox request page paddr=0x{:08x} action={reuse_action}",
            frame.paddr()
        ));
        return Ok(*frame);
    }

    let frame = hal
        .alloc_dma_frame_low_attr(sel4_sys::seL4_ARM_Page_Uncached)
        .map_err(|_| HalError::Unsupported("mailbox-dma"))?;
    let mapped = MappedRegs {
        paddr: frame.paddr(),
        vaddr: frame.ptr().as_ptr() as usize,
    };
    emit_breadcrumb(format_args!(
        "[pi4-wifi] mailbox request page paddr=0x{:08x} action={alloc_action}",
        mapped.paddr()
    ));
    core::mem::forget(frame);
    *shared_request = Some(mapped);
    Ok(mapped)
}

struct GpioBank {
    regs: MappedRegs,
}

impl GpioBank {
    fn new<H>(hal: &mut H) -> Result<Self, HalError>
    where
        H: DeviceHal<Error = HalError>,
    {
        let regs = if let Some(regs) = cloned_pinned_regs(&PINNED_GPIO_REGS) {
            regs
        } else {
            let mut prefix_maps = Vec::new();
            let regs = map_exact(hal, &GPIO_PAGE_PADDR_CANDIDATES, &mut prefix_maps)?;
            let regs = MappedRegs::from_frame(&regs);
            let mut slot = PINNED_GPIO_REGS.lock();
            if slot.is_none() {
                *slot = Some(regs);
            }
            regs
        };
        Ok(Self { regs })
    }

    fn configure_wifi_sdio_pins(&self) {
        emit_breadcrumb(format_args!("[pi4-wifi] gpio sdio mux begin"));
        for &pin in &PI4_WIFI_SDIO_PINS {
            self.set_function(pin, BCM2711_GPIO_ALT3);
        }
        for (&pin, &pull) in PI4_WIFI_SDIO_PINS.iter().zip(PI4_WIFI_SDIO_PULLS.iter()) {
            self.set_pull(pin, pull);
        }
        let fsel3 = self.read32(bcm2711_gpfsel_offset(PI4_WIFI_SDIO_PINS[0]));
        let pud2 = self.read32(bcm2711_puppdn_offset(PI4_WIFI_SDIO_PINS[0]));
        emit_breadcrumb(format_args!(
            "[pi4-wifi] gpio sdio mux ready fsel3=0x{fsel3:08x} pud2=0x{pud2:08x}"
        ));
    }

    fn set_function(&self, gpio: u32, function: u32) {
        let offset = bcm2711_gpfsel_offset(gpio);
        let value = update_bcm2711_gpio_function(self.read32(offset), gpio, function);
        self.write32(offset, value);
    }

    fn set_pull(&self, gpio: u32, pull: u32) {
        let offset = bcm2711_puppdn_offset(gpio);
        let value = update_bcm2711_gpio_pull(self.read32(offset), gpio, pull);
        self.write32(offset, value);
    }

    fn read32(&self, offset: usize) -> u32 {
        let base = self.regs.vaddr();
        // SAFETY: `regs` is a mapped BCM2711 GPIO MMIO page owned by the HAL, and
        // all accesses use aligned 32-bit register offsets within that page.
        unsafe { ptr::read_volatile((base + offset) as *const u32) }
    }

    fn write32(&self, offset: usize, value: u32) {
        let base = self.regs.vaddr();
        // SAFETY: `regs` is a mapped BCM2711 GPIO MMIO page owned by the HAL, and
        // all accesses use aligned 32-bit register offsets within that page.
        unsafe { ptr::write_volatile((base + offset) as *mut u32, value) };
        for _ in 0..SDHCI_WRITE_DELAY_LOOPS {
            spin_loop();
        }
    }
}

fn bcm2711_gpfsel_offset(gpio: u32) -> usize {
    BCM2711_GPFSEL0 + ((gpio as usize) / 10) * 4
}

fn bcm2711_gpfsel_shift(gpio: u32) -> u32 {
    (gpio % 10) * 3
}

fn bcm2711_puppdn_offset(gpio: u32) -> usize {
    BCM2711_GPPUPPDN0 + ((gpio as usize) / 16) * 4
}

fn bcm2711_puppdn_shift(gpio: u32) -> u32 {
    (gpio % 16) * 2
}

fn update_bcm2711_gpio_function(word: u32, gpio: u32, function: u32) -> u32 {
    let shift = bcm2711_gpfsel_shift(gpio);
    let mask = BCM2835_GPIO_FSEL_MASK << shift;
    (word & !mask) | ((function & BCM2835_GPIO_FSEL_MASK) << shift)
}

fn update_bcm2711_gpio_pull(word: u32, gpio: u32, pull: u32) -> u32 {
    let shift = bcm2711_puppdn_shift(gpio);
    let mask = BCM2711_GPIO_PULL_MASK << shift;
    (word & !mask) | ((pull & BCM2711_GPIO_PULL_MASK) << shift)
}

fn emit_breadcrumb(args: core::fmt::Arguments<'_>) {
    let mut line = heapless::String::<224>::new();
    let _ = core::fmt::Write::write_fmt(&mut line, args);
    boot_log::force_uart_line(line.as_str());
}

#[inline]
fn merge_u8_word(word: u32, offset: usize, value: u8) -> u32 {
    let shift = ((offset & 0x3) * 8) as u32;
    let mask = !(0xFFu32 << shift);
    (word & mask) | (u32::from(value) << shift)
}

#[inline]
fn merge_u16_word(word: u32, offset: usize, value: u16) -> u32 {
    let shift = ((offset & 0x2) * 8) as u32;
    let mask = !(0xFFFFu32 << shift);
    (word & mask) | (u32::from(value) << shift)
}

#[inline]
const fn backplane_small_access_addr(addr: u32) -> u32 {
    addr
}

#[inline]
const fn backplane_byte_function_addr(addr: u32) -> u32 {
    addr & BACKPLANE_ADDRESS_MASK
}

#[inline]
const fn backplane_transfer_function_addr(addr: u32) -> u32 {
    (addr & BACKPLANE_ADDRESS_MASK) | BACKPLANE_32BIT_FLAG
}

#[inline]
const fn backplane_word_aligned_addr(addr: u32) -> u32 {
    addr & !0x3
}

#[inline]
const fn backplane_word_increment_addr() -> bool {
    false
}

#[inline]
const fn backplane_word_function_addr(addr: u32) -> u32 {
    backplane_transfer_function_addr(addr)
}

#[inline]
const fn core_ctrl_function_addr(addr: u32) -> u32 {
    backplane_word_function_addr(backplane_word_aligned_addr(addr))
}

#[inline]
const fn core_ctrl_current_window_addr(addr: u32) -> u32 {
    addr & BACKPLANE_ADDRESS_MASK
}

#[inline]
const fn core_ctrl_trace_function_addr(addr: u32) -> u32 {
    core_ctrl_function_addr(addr)
}

#[inline]
const fn backplane_word_byte_shift(addr: u32) -> u32 {
    (addr & 0x3) * 8
}

#[inline]
const fn backplane_window_base(addr: u32) -> u32 {
    addr & BACKPLANE_WINDOW_MASK
}

#[inline]
fn backplane_window_reprogram_needed(programmed_window: Option<u32>, addr: u32) -> bool {
    match programmed_window {
        Some(window) => window != backplane_window_base(addr),
        None => true,
    }
}

#[inline]
const fn backplane_window_register_bytes(addr: u32) -> (u8, u8, u8) {
    let window = backplane_window_base(addr);
    (
        ((window >> 8) & 0xFF) as u8,
        ((window >> 16) & 0xFF) as u8,
        ((window >> 24) & 0xFF) as u8,
    )
}

#[inline]
fn backplane_window_program_sequence(
    window_low: u8,
    window_mid: u8,
    window_high: u8,
) -> [(&'static str, u32, u8); 3] {
    [
        ("high", SBSDIO_FUNC1_SBADDRHIGH, window_high),
        ("mid", SBSDIO_FUNC1_SBADDRMID, window_mid),
        ("low", SBSDIO_FUNC1_SBADDRLOW, window_low),
    ]
}

#[inline]
const fn core_ctrl_access_mode_label() -> &'static str {
    "cmd53-windowed-read32-cmd53-byte-current-window fallback=cmd53-byte-rewindow"
}

#[inline]
const fn core_ctrl_reset_assert_access_mode_label() -> &'static str {
    "cmd53-word-windowed fallback=cmd52-byte-current-window-rewindow"
}

#[inline]
const fn core_ctrl_reset_clear_access_mode_label() -> &'static str {
    "cmd53-word-windowed fallback=cmd52-byte-current-window"
}

#[inline]
const fn core_ctrl_reset_clear_retry_access_mode_label() -> &'static str {
    "cmd52-byte-current-window retry=preserved-cache"
}

#[inline]
const fn core_ctrl_postreset_access_mode_label(_base: u32, _offset: u32) -> &'static str {
    "cmd53-byte-current-window fallback=cmd53-byte-rewindow"
}

#[inline]
const fn core_ctrl_postreset_read_uses_cmd52_current_window(base: u32, _offset: u32) -> bool {
    base == CYW43_ARMCR4_CORE_BASE
}

#[inline]
const fn core_ctrl_postreset_read_access_mode_label(base: u32, offset: u32) -> &'static str {
    if core_ctrl_postreset_read_uses_cmd52_current_window(base, offset) {
        "cmd52-byte-current-window retry=cmd52-byte-rewindow"
    } else {
        "cmd53-windowed-read32-cmd53-byte-current-window fallback=cmd53-byte-rewindow"
    }
}

#[inline]
const fn core_ctrl_clear_reset_read_uses_cmd52_current_window(base: u32, offset: u32) -> bool {
    base == CYW43_ARMCR4_CORE_BASE && offset == AI_RESETCTRL_OFFSET
}

#[inline]
const fn core_ctrl_clear_reset_read_access_mode_label(base: u32, offset: u32) -> &'static str {
    if core_ctrl_clear_reset_read_uses_cmd52_current_window(base, offset) {
        "cmd52-byte-current-window retry=cmd52-byte-rewindow"
    } else {
        "cmd53-windowed-read32-cmd53-byte-current-window fallback=cmd53-byte-rewindow"
    }
}

#[inline]
const fn core_ctrl_in_reset_access_mode_label(base: u32, offset: u32) -> &'static str {
    if core_ctrl_in_reset_write_uses_word_path(base, offset) {
        "cmd53-word-windowed-in-reset fallback=cmd52-current-window-rewindow"
    } else {
        "cmd52-byte-current-window fallback=cmd52-byte-rewindow"
    }
}

fn log_core_ctrl_access(op: &'static str, base: u32, offset: u32, value: Option<u8>) {
    let addr = base.saturating_add(offset);
    let trace_bus = core_ctrl_trace_function_addr(addr);
    let bus = if op == "write8" {
        core_ctrl_current_window_addr(addr)
    } else {
        trace_bus
    };
    let shift = backplane_word_byte_shift(addr);
    match value {
        Some(value) => emit_breadcrumb(format_args!(
            "[pi4-wifi] firmware core-ctrl access op={op} mode={} base=0x{base:08x} off=0x{offset:03x} addr=0x{addr:08x} window=0x{window:08x} bus=0x{bus:05x} trace_bus=0x{trace_bus:05x} shift={shift} inc={} value=0x{value:02x}",
            core_ctrl_access_mode_label(),
            backplane_word_increment_addr() as u8,
            window = addr & BACKPLANE_WINDOW_MASK,
        )),
        None => emit_breadcrumb(format_args!(
            "[pi4-wifi] firmware core-ctrl access op={op} mode={} base=0x{base:08x} off=0x{offset:03x} addr=0x{addr:08x} window=0x{window:08x} bus=0x{bus:05x} trace_bus=0x{trace_bus:05x} shift={shift} inc={}",
            core_ctrl_access_mode_label(),
            backplane_word_increment_addr() as u8,
            window = addr & BACKPLANE_WINDOW_MASK,
        )),
    }
}

fn log_core_ctrl_reset_write(base: u32, offset: u32, value: u8, mode: &'static str) {
    let addr = base.saturating_add(offset);
    emit_breadcrumb(format_args!(
        "[pi4-wifi] firmware core-ctrl reset-write mode={} base=0x{base:08x} off=0x{offset:03x} addr=0x{addr:08x} window=0x{window:08x} bus=0x{bus:05x} trace_bus=0x{trace_bus:05x} shift={shift} inc={inc} value=0x{value:02x}",
        mode,
        bus = core_ctrl_current_window_addr(addr),
        trace_bus = core_ctrl_trace_function_addr(addr),
        shift = backplane_word_byte_shift(addr),
        inc = backplane_word_increment_addr() as u8,
        window = addr & BACKPLANE_WINDOW_MASK,
    ));
}

fn log_core_ctrl_in_reset_write(base: u32, offset: u32, value: u8) {
    let addr = base.saturating_add(offset);
    emit_breadcrumb(format_args!(
        "[pi4-wifi] firmware core-ctrl in-reset-write mode={} base=0x{base:08x} off=0x{offset:03x} addr=0x{addr:08x} bus=0x{bus:05x} trace_bus=0x{trace_bus:05x} value=0x{value:02x}",
        core_ctrl_in_reset_access_mode_label(base, offset),
        bus = core_ctrl_trace_function_addr(addr),
        trace_bus = core_ctrl_trace_function_addr(addr),
    ));
}

fn log_core_ctrl_postreset_write(base: u32, offset: u32, value: u8) {
    let addr = base.saturating_add(offset);
    emit_breadcrumb(format_args!(
        "[pi4-wifi] firmware core-ctrl postreset-write mode={} base=0x{base:08x} off=0x{offset:03x} addr=0x{addr:08x} window=0x{window:08x} bus=0x{bus:05x} trace_bus=0x{trace_bus:05x} shift={shift} inc={inc} value=0x{value:02x}",
        core_ctrl_postreset_access_mode_label(base, offset),
        bus = core_ctrl_current_window_addr(addr),
        trace_bus = core_ctrl_trace_function_addr(addr),
        shift = backplane_word_byte_shift(addr),
        inc = backplane_word_increment_addr() as u8,
        window = addr & BACKPLANE_WINDOW_MASK,
    ));
}

fn log_core_ctrl_postreset_read(base: u32, offset: u32) {
    let addr = base.saturating_add(offset);
    emit_breadcrumb(format_args!(
        "[pi4-wifi] firmware core-ctrl access op=read8 mode={} base=0x{base:08x} off=0x{offset:03x} addr=0x{addr:08x} window=0x{window:08x} bus=0x{bus:05x} trace_bus=0x{trace_bus:05x} shift={shift} inc={inc}",
        core_ctrl_postreset_read_access_mode_label(base, offset),
        bus = core_ctrl_trace_function_addr(addr),
        trace_bus = core_ctrl_trace_function_addr(addr),
        shift = backplane_word_byte_shift(addr),
        inc = backplane_word_increment_addr() as u8,
        window = addr & BACKPLANE_WINDOW_MASK,
    ));
}

fn log_core_ctrl_clear_reset_read(base: u32, offset: u32) {
    let addr = base.saturating_add(offset);
    emit_breadcrumb(format_args!(
        "[pi4-wifi] firmware core-ctrl access op=read8-clear-reset mode={} base=0x{base:08x} off=0x{offset:03x} addr=0x{addr:08x} window=0x{window:08x} bus=0x{bus:05x} trace_bus=0x{trace_bus:05x} shift={shift} inc={inc}",
        core_ctrl_clear_reset_read_access_mode_label(base, offset),
        bus = core_ctrl_current_window_addr(addr),
        trace_bus = core_ctrl_trace_function_addr(addr),
        shift = backplane_word_byte_shift(addr),
        inc = backplane_word_increment_addr() as u8,
        window = addr & BACKPLANE_WINDOW_MASK,
    ));
}

#[inline]
const fn core_ctrl_in_reset_write_uses_word_path(base: u32, offset: u32) -> bool {
    base == CYW43_ARMCR4_CORE_BASE && offset == AI_IOCTRL_OFFSET
}

#[inline]
const fn core_reset_needs_postreset_window_reprime(base: u32) -> bool {
    base == CYW43_SOCRAM_CORE_BASE
}

#[inline]
const fn core_ctrl_can_skip_redundant_in_reset_write(
    base: u32,
    asserted_reset: bool,
    prior_value: u8,
    next_value: u8,
) -> bool {
    asserted_reset && base == CYW43_SOCRAM_CORE_BASE && prior_value == next_value
}

#[inline]
const fn core_ctrl_can_defer_in_reset_readback(
    base: u32,
    asserted_reset: bool,
    skipped_write: bool,
) -> bool {
    (base == CYW43_SOCRAM_CORE_BASE && asserted_reset && skipped_write)
        || (base == CYW43_D11_CORE_BASES[0] && asserted_reset)
}

#[inline]
fn core_ctrl_can_defer_in_reset_reset_read_error(base: u32, offset: u32, err: &HalError) -> bool {
    base == CYW43_ARMCR4_CORE_BASE
        && offset == AI_RESETCTRL_OFFSET
        && is_armcr4_postreset_fragile_read_error(err)
}

#[inline]
const fn core_ctrl_in_reset_reset_read_error_reason(base: u32) -> &'static str {
    if base == CYW43_ARMCR4_CORE_BASE {
        "armcr4-fragile-in-reset-reset-read"
    } else {
        "core-fragile-in-reset-reset-read"
    }
}

#[inline]
const fn core_disable_reads_entry_state(base: u32) -> bool {
    base == CYW43_SOCRAM_CORE_BASE
}

#[inline]
const fn core_reset_prepare_hold_value(reset: u8) -> u8 {
    reset | AI_CORE_PRERESET_IOCTRL
}

#[inline]
const fn core_reset_can_skip_pre_clear_in_reset_write(base: u32, skipped_disable: bool) -> bool {
    skipped_disable && base == CYW43_SOCRAM_CORE_BASE
}

#[inline]
const fn backplane_window_differs_by_mid_byte_only(
    current_window_base: u32,
    target_window_addr: u32,
) -> bool {
    let (current_low, current_mid, current_high) =
        backplane_window_register_bytes(current_window_base);
    let (target_low, target_mid, target_high) = backplane_window_register_bytes(target_window_addr);
    current_low == target_low && current_mid != target_mid && current_high == target_high
}

#[inline]
const fn core_ctrl_can_defer_clear_reset_readback(base: u32, attempt: usize) -> bool {
    attempt == 0 && base == CYW43_SOCRAM_CORE_BASE
}

#[inline]
const fn core_ctrl_clear_reset_readback_error_reason(base: u32) -> &'static str {
    if base == CYW43_ARMCR4_CORE_BASE {
        "armcr4-release-clear-reset-must-be-proven-before-ht"
    } else {
        "core-clear-reset-readback-required"
    }
}

#[inline]
fn core_ctrl_can_defer_clear_reset_read_error(base: u32, offset: u32, err: &HalError) -> bool {
    base == CYW43_ARMCR4_CORE_BASE
        && offset == AI_RESETCTRL_OFFSET
        && (is_sdio_cmd52_access_error(err) || is_armcr4_postreset_fragile_read_error(err))
}

#[inline]
const fn core_ctrl_clear_reset_read_deferred_reason(base: u32) -> &'static str {
    if base == CYW43_ARMCR4_CORE_BASE {
        "armcr4-clear-reset-read-fragile-after-release"
    } else {
        "core-clear-reset-read-deferred"
    }
}

#[inline]
const fn core_reset_can_skip_disable(base: u32, prereset: u8, reset: u8, postreset: u8) -> bool {
    // SOCRAM is already held from the immediately preceding disable. ARMCR4
    // must still run Linux's disable phase on active release so CPUHALT is
    // cleared while reset is asserted.
    base == CYW43_SOCRAM_CORE_BASE && prereset == 0 && reset == 0 && postreset == 0
}

#[inline]
const fn core_reset_needs_clear_reset_prewrite_settle(_base: u32, _attempt: usize) -> bool {
    false
}

#[inline]
const fn core_reset_can_retry_clear_reset_write(base: u32, attempt: usize) -> bool {
    base == CYW43_SOCRAM_CORE_BASE && attempt == 0
}

#[inline]
const fn core_reset_needs_clear_reset_ht_assist(base: u32) -> bool {
    base == CYW43_SOCRAM_CORE_BASE
}

#[inline]
const fn core_disable_uses_upstream_socram_disable(base: u32, prereset: u8, reset: u8) -> bool {
    base == CYW43_SOCRAM_CORE_BASE && prereset == 0 && reset == 0
}

#[inline]
const fn core_control_settle_loops(base: u32) -> usize {
    if base == CYW43_ARMCR4_CORE_BASE {
        CYW43_ARMCR4_CONTROL_SETTLE_LOOPS
    } else {
        CYW43_CORE_CONTROL_SETTLE_LOOPS
    }
}

#[inline]
const fn clear_reset_keepalive_chunk_loops(remaining_loops: usize) -> usize {
    if remaining_loops > CYW43_CORE_CONTROL_SETTLE_LOOPS {
        CYW43_CORE_CONTROL_SETTLE_LOOPS
    } else {
        remaining_loops
    }
}

#[inline]
const fn ht_clock_assist_shadow_is_complete(
    last_wakeupctrl: Option<u8>,
    last_sleepcsr: Option<u8>,
    last_cardcap: Option<u8>,
) -> bool {
    match (last_wakeupctrl, last_sleepcsr, last_cardcap) {
        (Some(wake), Some(sleep), Some(cardcap)) => {
            (wake & SBSDIO_WAKE_TILL_HT_AVAIL) == SBSDIO_WAKE_TILL_HT_AVAIL
                && sleepcsr_device_on_awake(sleep)
                && cardcap == cyw43455_cardcap_command_decode_value()
        }
        _ => false,
    }
}

#[inline]
const fn post_download_ht_request_primes_wake_sideband() -> bool {
    // Hardware traces now prove firmware upload/release while CHIPCLKCSR stays
    // at HT_REQ|ALP_AVAIL with WAKEUPCTRL unset. Prime the Broadcom wake
    // sideband before the post-release CLK_AVAIL request. Pi 4 CYW43455 then
    // permits the forced ALP/KSO post-release tuple to reach strict Function 2
    // enablement; Function 2 readiness still gates the firmware channel.
    true
}

#[inline]
fn post_download_ht_stage_primes_wake_sideband(stage: &'static str) -> bool {
    matches!(
        stage,
        "wait-ht-clock" | "debug-probe-ht" | "post-function2-sr-init"
    )
}

#[inline]
const fn post_download_ht_wakeupctrl_value(last_wakeupctrl: Option<u8>) -> u8 {
    match last_wakeupctrl {
        Some(value) => value | SBSDIO_WAKE_TILL_HT_AVAIL,
        None => SBSDIO_WAKE_TILL_HT_AVAIL,
    }
}

#[inline]
const fn post_download_ht_cardcap_value() -> u8 {
    cyw43455_cardcap_command_decode_value()
}

#[inline]
const fn post_download_ht_sleepcsr_value(last_sleepcsr: Option<u8>) -> u8 {
    let preserved_devon = match last_sleepcsr {
        Some(value) => value & SBSDIO_FUNC1_SLEEPCSR_DEVON_MASK,
        None => 0,
    };
    SBSDIO_FUNC1_SLEEPCSR_KSO_EN | preserved_devon
}

#[inline]
const fn post_download_ht_sleepcsr_ready_for_function2(sleep: u8) -> bool {
    sleepcsr_kso_acknowledged(sleep)
}

#[inline]
const fn post_download_ht_sleepcsr_uses_linux_clear_set() -> bool {
    false
}

#[inline]
const fn post_download_ht_sleepcsr_clear_set_is_nonterminal() -> bool {
    post_download_devon_before_ht_is_diagnostic()
}

#[inline]
const fn post_download_ht_sideband_shadow_is_complete(
    last_wakeupctrl: Option<u8>,
    last_sleepcsr: Option<u8>,
    last_cardcap: Option<u8>,
) -> bool {
    match (last_wakeupctrl, last_sleepcsr, last_cardcap) {
        (Some(wake), Some(sleep), Some(cardcap)) => {
            (wake & SBSDIO_WAKE_TILL_HT_AVAIL) == SBSDIO_WAKE_TILL_HT_AVAIL
                && post_download_ht_sleepcsr_ready_for_function2(sleep)
                && cardcap == cyw43455_cardcap_command_decode_value()
        }
        _ => false,
    }
}

const fn post_download_forced_alp_kso_sideband_allows_function2_probe(
    last_wakeupctrl: Option<u8>,
    last_sleepcsr: Option<u8>,
    last_cardcap: Option<u8>,
) -> bool {
    let _ = last_cardcap;
    match (last_wakeupctrl, last_sleepcsr) {
        (Some(wake), Some(sleep)) => {
            (wake & SBSDIO_WAKE_TILL_HT_AVAIL) == SBSDIO_WAKE_TILL_HT_AVAIL
                && post_download_ht_sleepcsr_ready_for_function2(sleep)
        }
        _ => false,
    }
}

#[inline]
const fn pre_function2_ht_sideband_programs_sr_registers() -> bool {
    // Generic pre-F2 recovery refreshes remain KSO-only. The post-download HT
    // edge primes wake/CMD14/KSO and polls DEVON readback separately, while the
    // captured Linux CHIPCLKCSR proof remains the only pre-F2 clock gate.
    false
}

#[inline]
const fn pre_function2_ht_sideband_shadow_is_complete(last_sleepcsr: Option<u8>) -> bool {
    match last_sleepcsr {
        Some(sleep) => sleepcsr_kso_acknowledged(sleep),
        None => false,
    }
}

#[inline]
fn is_sdhci_command_error(err: &HalError) -> bool {
    matches!(err, HalError::Unsupported("sdhci-command-error"))
}

#[inline]
fn is_sdhci_int_timeout(err: &HalError) -> bool {
    matches!(err, HalError::Unsupported("sdhci-int-timeout"))
}

#[inline]
fn is_sdhci_transfer_finish_error_reason(reason: &str) -> bool {
    matches!(
        reason,
        "sdhci-transfer-finish"
            | "sdhci-transfer-finish-timeout"
            | "sdhci-transfer-finish-crc"
            | "sdhci-transfer-finish-end-bit"
            | "sdhci-transfer-finish-index"
            | "sdhci-transfer-finish-data-timeout"
            | "sdhci-transfer-finish-data-crc"
            | "sdhci-transfer-finish-data-end-bit"
            | "sdhci-transfer-finish-error"
    )
}

#[inline]
fn is_sdhci_fragile_read_error(err: &HalError) -> bool {
    is_sdhci_command_error(err) || is_sdhci_int_timeout(err)
}

#[inline]
fn firmware_verify_readback_can_be_treated_as_unavailable(err: &HalError) -> bool {
    is_sdhci_int_timeout(err) || is_sdhci_io_path_error(err) || is_sdio_cmd52_access_error(err)
}

#[inline]
const fn firmware_download_readback_verify_required(_prewrite_ht_ready: bool) -> bool {
    // Linux brcmfmac only compiles the full RAM compare path under DEBUG.
    // The Pi 4 production path writes firmware, writes NVRAM, then releases
    // ARMCR4 without forcing a Function 1 RAM readback first.
    false
}

#[inline]
const fn firmware_download_readback_status(
    readback_required: bool,
    verified: bool,
) -> &'static str {
    if verified {
        "verified-bounded-readback"
    } else if readback_required {
        "required-readback-not-verified"
    } else {
        "linux-debug-readback-skipped"
    }
}

const PI4_WIFI_LINUX_CAPTURE_RAW_NVRAM_LEN: usize = 2_074;
const PI4_WIFI_LINUX_CAPTURE_NORMALIZED_NVRAM_LEN: usize = 1_744;
const PI4_WIFI_LINUX_CAPTURE_NVRAM_WITH_TAIL_LEN: usize = 1_748;

#[inline]
const fn pi4_wifi_nvram_linux_shape_state(raw_len: usize, normalized_len: usize) -> &'static str {
    if raw_len != PI4_WIFI_LINUX_CAPTURE_RAW_NVRAM_LEN {
        "raw-len-mismatch"
    } else if normalized_len != PI4_WIFI_LINUX_CAPTURE_NORMALIZED_NVRAM_LEN {
        "normalized-len-mismatch"
    } else if normalized_len.saturating_add(4) != PI4_WIFI_LINUX_CAPTURE_NVRAM_WITH_TAIL_LEN {
        "tail-total-mismatch"
    } else {
        "linux-shaped"
    }
}

#[inline]
fn firmware_contract_nvram_upload_len(bundle: WifiFirmwareBundle<'static>) -> usize {
    normalize_nvram(bundle.nvram).len()
}

#[inline]
const fn reset_vector_readback_verify_required(firmware_download_verified: bool) -> bool {
    firmware_download_verified
}

#[inline]
fn is_sdhci_io_path_error(err: &HalError) -> bool {
    match err {
        HalError::Unsupported(reason) => {
            matches!(
                *reason,
                "sdhci-command-error" | "sdhci-transfer-command" | "sdhci-transfer-data"
            ) || is_sdhci_transfer_finish_error_reason(reason)
        }
        _ => false,
    }
}

#[inline]
fn control_plane_frame_transfer_error_needs_terminate(err: &HalError) -> bool {
    is_sdhci_io_path_error(err) || is_sdhci_int_timeout(err)
}

fn is_sdio_cmd52_access_error(err: &HalError) -> bool {
    matches!(
        err,
        HalError::Unsupported("sdio-cmd52-read") | HalError::Unsupported("sdio-cmd52-write")
    )
}

#[inline]
fn is_armcr4_postreset_fragile_read_error(err: &HalError) -> bool {
    is_sdhci_io_path_error(err)
        || is_sdhci_int_timeout(err)
        || matches!(err, HalError::Unsupported("sdio-cmd52-read"))
}

#[inline]
fn control_plane_startup_link_rescue_exhausted_error(
    snapshot_exact_error: &'static str,
    cached_snapshot_exact_error: Option<&'static str>,
) -> &'static str {
    let exact_error = cached_snapshot_exact_error
        .filter(|exact_error| !exact_error.is_empty())
        .unwrap_or(snapshot_exact_error);
    if exact_error.is_empty() {
        "cyw43-control-plane-startup-link-rescue-budget-exhausted"
    } else {
        exact_error
    }
}

#[inline]
const fn io_direct_cmd53_byte_fallback_allowed(function: SdioFunction) -> bool {
    matches!(function, SdioFunction::Function1)
}

#[inline]
fn chipcommon_config_can_assume_write_commit(addr: u32, err: &HalError) -> bool {
    let _ = addr;
    let _ = err;
    false
}

#[inline]
fn chipcommon_config_can_assume_window_commit(err: &HalError) -> bool {
    let _ = err;
    false
}

#[inline]
fn firmware_backplane_write_can_retry(err: &HalError, attempt: usize) -> bool {
    attempt == 0 && is_sdhci_io_path_error(err)
}

#[inline]
fn firmware_window_write_can_retry(err: &HalError, attempt: usize) -> bool {
    attempt == 0 && chipcommon_config_can_assume_window_commit(err)
}

#[inline]
const fn firmware_transfer_uses_byte_mode(byte_mode_fallback: bool) -> bool {
    byte_mode_fallback
}

#[inline]
const fn firmware_upload_prefers_byte_mode(current_clock_hz: u32, ht_ready: bool) -> bool {
    let _ = current_clock_hz;
    !ht_ready
}

#[inline]
const fn control_plane_clock_target_hz(current_clock_hz: u32, preferred_data_clock_hz: u32) -> u32 {
    let floor = if preferred_data_clock_hz >= CYW43_CONTROL_PLANE_CLOCK_HZ {
        preferred_data_clock_hz
    } else {
        CYW43_CONTROL_PLANE_CLOCK_HZ
    };
    if current_clock_hz >= floor {
        current_clock_hz
    } else {
        floor
    }
}

#[inline]
const fn pre_ht_control_plane_clock_target_hz(current_clock_hz: u32) -> u32 {
    control_plane_clock_target_hz(current_clock_hz, CYW43_CONTROL_PLANE_CLOCK_HZ)
}

#[inline]
const fn firmware_core_reset_clock_target_hz(current_clock_hz: u32) -> u32 {
    pre_ht_control_plane_clock_target_hz(current_clock_hz)
}

#[inline]
const fn sdio_cccr_speed_supports_high_speed(speed: u8) -> bool {
    (speed & SDIO_CCCR_SPEED_SHS) != 0
}

#[inline]
const fn sdio_cccr_speed_ehs_value(speed: u8) -> u8 {
    speed | SDIO_CCCR_SPEED_EHS
}

#[inline]
const fn post_download_ht_clock_target_hz(
    current_clock_hz: u32,
    selected_bulk_clock_hz: u32,
) -> u32 {
    // Match the Pi 4 firmware/Linux high-speed request. The BCM2711 SDHCI
    // parent clock correction makes the encoded divider deliver Linux's
    // observed 41.666667 MHz actual link for a 50 MHz request.
    let linux_floor = if selected_bulk_clock_hz > CYW43_CONTROL_PLANE_CLOCK_HZ {
        selected_bulk_clock_hz
    } else {
        CYW43_CONTROL_PLANE_CLOCK_HZ
    };
    if linux_floor > current_clock_hz {
        linux_floor
    } else {
        current_clock_hz
    }
}

#[inline]
const fn firmware_activation_clock_target_hz(
    current_clock_hz: u32,
    selected_bulk_clock_hz: u32,
) -> u32 {
    post_download_ht_clock_target_hz(current_clock_hz, selected_bulk_clock_hz)
}

#[inline]
const fn bcm2711_sdhci_effective_base_clock_hz(mailbox_rate_hz: u32) -> u32 {
    if mailbox_rate_hz == BCM2711_SDIO_MAILBOX_CLOCK_HZ {
        BCM2711_SDIO_EFFECTIVE_BASE_CLOCK_HZ
    } else {
        mailbox_rate_hz
    }
}

#[inline]
fn sdhci_spec300_divider_for_base_clock(base_clock_hz: u32, target_hz: u32) -> u16 {
    if base_clock_hz <= target_hz {
        1
    } else {
        let mut div = 2u16;
        while div < 2046 && (base_clock_hz / u32::from(div)) > target_hz {
            div = div.saturating_add(2);
        }
        div
    }
}

#[inline]
fn firmware_phase_can_retry(err: &HalError, attempt: usize) -> bool {
    attempt == 0
        && (is_sdhci_io_path_error(err)
            || is_sdio_cmd52_access_error(err)
            || matches!(err, HalError::Unsupported("sdhci-int-timeout")))
}

#[inline]
const fn setup_firmware_channel_uses_experimental_order(
    allow_function2_ready_bypass: bool,
) -> bool {
    let _ = allow_function2_ready_bypass;
    // Function-2-first sequencing on the no-HT path has proven to hide partial
    // mailbox/interrupt-mask programming without ever producing a real ready
    // indication. Keep the firmware-channel setup order stable even when the
    // bring-up path is still willing to bypass IORX.
    false
}

#[inline]
const fn firmware_channel_write_restore_clock_hz(
    experimental_no_ht_transport: bool,
    current_clock_hz: u32,
) -> Option<u32> {
    let _ = experimental_no_ht_transport;
    let _ = current_clock_hz;
    // Keep the Pi 4 BCM43455 setup path aligned with Linux brcmfmac:
    // once the bus has been promoted for firmware bring-up, do not demote the
    // mailbox / Function-2 / hostintmask programming sequence back to 400 kHz.
    None
}

#[inline]
const fn setup_firmware_channel_pref2_write_restore_clock_hz(
    experimental_no_ht_transport: bool,
    startup_link_stabilized: bool,
    current_clock_hz: u32,
) -> Option<u32> {
    let _ = experimental_no_ht_transport;
    let _ = startup_link_stabilized;
    let _ = current_clock_hz;
    // Linux keeps the BCM43455 control path on the promoted SDIO clock while
    // it brings Function 2 and firmware mailboxes online. Dropping this window
    // back to 400 kHz leaves the chip with ALP/force-HT state but no observed
    // HT availability, which then latches Function 2 without IORX.
    None
}

#[inline]
const fn rearm_firmware_channel_restore_clock_hz(
    experimental_no_ht_transport: bool,
    current_clock_hz: u32,
    function2_ready_budget: SdioFunctionReadyBudget,
) -> Option<u32> {
    // The Pi 4 startup-link strict-recovery lane still needs the immediate
    // Function 2 retry to happen on the promoted first-reply clock, but the
    // preceding F1/mailbox rearm writes have proven fragile at 12.5 MHz. Ask
    // the caller to temporarily drop to startup clock for those writes, then
    // restore the promoted clock before the next Function 2 read.
    if experimental_no_ht_transport
        && matches!(
            function2_ready_budget,
            SdioFunctionReadyBudget::ControlPlaneReplyStrictRecovery
        )
        && current_clock_hz > CYW43_STARTUP_CLOCK_HZ
    {
        Some(current_clock_hz)
    } else {
        firmware_channel_write_restore_clock_hz(experimental_no_ht_transport, current_clock_hz)
    }
}

#[inline]
fn firmware_channel_write_needs_low_clock_retry(
    experimental_no_ht_transport: bool,
    startup_link_stabilized: bool,
    current_clock_hz: u32,
    err: &HalError,
) -> bool {
    (experimental_no_ht_transport || !startup_link_stabilized)
        && current_clock_hz > CYW43_STARTUP_CLOCK_HZ
        && (is_sdhci_io_path_error(err) || is_sdio_cmd52_access_error(err))
}

#[inline]
fn setup_firmware_channel_can_assume_write_committed(
    allow_function2_ready_bypass: bool,
    attempt: usize,
    err: &HalError,
) -> bool {
    let _ = allow_function2_ready_bypass;
    let _ = attempt;
    let _ = err;
    false
}

#[inline]
const fn firmware_stage_allows_function2_ready_bypass(experimental_no_ht_transport: bool) -> bool {
    // brcmfmac treats Function 2 readiness as a real SDIO contract. The Pi 4
    // forced ALP/KSO edge can, however, latch IOEX without surfacing IOR2 while
    // Linux immediately proceeds to bounded F2 FIFO traffic. Limit that probe
    // to the explicit no-HT diagnostic lane; strict bring-up still requires
    // real IOR2.
    experimental_no_ht_transport
}

#[inline]
const fn firmware_stage_can_enter_bounded_no_ht_transport_after_soft_ht_timeout() -> bool {
    // The no-HT lane is only a firmware upload fallback and diagnostic state;
    // firmware-channel setup must prove the same HT clock contract Linux proves
    // before it enables Function 2.
    false
}

#[inline]
const fn required_ht_clock_soft_timeout_keeps_strict_transport(
    last_chipclkcsr: Option<u8>,
    last_wakeupctrl: Option<u8>,
    last_sleepcsr: Option<u8>,
    last_cardcap: Option<u8>,
) -> bool {
    !firmware_stage_can_enter_bounded_no_ht_transport_after_soft_ht_timeout()
        || !ht_clock_timeout_can_enter_bounded_no_ht_transport(
            last_chipclkcsr,
            last_wakeupctrl,
            last_sleepcsr,
            last_cardcap,
        )
}

#[inline]
fn startup_link_first_blocker_for_snapshot_stage(stage: &'static str) -> Option<&'static str> {
    match stage {
        "post-firmware-ready-function2-strict-repoll-fail" => Some("firmware-channel-f2"),
        "control-plane-passive-startup-link-timeout"
        | "control-plane-passive-startup-link-timeout-no-reply"
        | "control-plane-passive-startup-link-timeout-probe-fail"
        | "control-plane-reply-sideband-unreadable-exhausted"
        | "control-plane-reply-speculative-read-empty"
        | "control-plane-reply-speculative-read-fail"
        | "control-plane-reply-strict-recover-fail"
        | "control-plane-startup-link-rearm-stalled"
        | "control-plane-promoted-rearm-stalled" => Some("first-control-plane-reply"),
        _ => None,
    }
}

