#[inline]
const fn sleepcsr_kso_acknowledged(sleep: u8) -> bool {
    (sleep & SBSDIO_FUNC1_SLEEPCSR_REQUIRED_WAKE_MASK) == SBSDIO_FUNC1_SLEEPCSR_REQUIRED_WAKE_MASK
}

#[inline]
const fn sleepcsr_devon_observed(sleep: u8) -> bool {
    (sleep & SBSDIO_FUNC1_SLEEPCSR_DEVON_MASK) != 0
}

#[inline]
const fn sleepcsr_device_on_awake(sleep: u8) -> bool {
    sleepcsr_kso_acknowledged(sleep) && sleepcsr_devon_observed(sleep)
}

#[inline]
const fn linux_sr_kso_clock_ready_from_sleepcsr(sleep: u8) -> bool {
    let _ = sleep;
    // KSO only proves that the sleep-retention sideband is awake. The HT clock
    // contract must still be proven from CHIPCLKCSR before Function 2 is
    // enabled.
    false
}

#[inline]
const fn post_download_devon_before_ht_is_diagnostic() -> bool {
    // On the Pi 4 non-SR firmware callback path, DEVON is useful sideband
    // evidence but is not a prerequisite for the forced ALP/KSO post-release
    // Function 2 edge.
    true
}

#[inline]
fn devon_before_ht_may_be_deferred_for_stage(stage: &'static str) -> bool {
    let _ = stage;
    // The post-download path writes KSO and observes DEVON directly without
    // allowing this generic helper to weaken DEVON waits for other diagnostic
    // callers.
    false
}

#[inline]
const fn ht_timeout_exact_error_after_firmware_release(
    firmware_download_verified: bool,
) -> &'static str {
    if firmware_download_verified {
        "cyw43-firmware-boot-timeout"
    } else {
        "cyw43-ht-clock-timeout-before-function2"
    }
}

const SDIO_CORECONTROL: u32 = 0x00;
const SDIO_CORESTATUS: u32 = 0x04;
const SDPCMD_REG_HOSTINTMASK: u32 = 0x24;
const SDPCMD_REG_FUNCTIONINTMASK: u32 = 0x34;
const SDPCMD_REG_TOSBMAILBOX: u32 = 0x40;
const SDPCMD_REG_TOSBMAILBOXDATA: u32 = 0x48;
const SDPCMD_REG_TOHOSTMAILBOXDATA: u32 = 0x4C;
const SDIO_INT_STATUS: u32 = 0x20;

const CC_F2RDY: u32 = 1 << 2;
const SMB_NAK: u32 = 1 << 0;
const SMB_INT_ACK: u32 = 1 << 1;
const I_HMB_SW_MASK: u32 = 0x0000_00F0;
const I_HMB_FC_CHANGE: u32 = 1 << 5;
const I_HMB_FRAME_IND: u32 = 1 << 6;
const I_HMB_HOST_INT: u32 = 1 << 7;
const I_CHIPACTIVE: u32 = 1 << 29;
const HOSTINTMASK: u32 = I_HMB_SW_MASK | I_CHIPACTIVE;
const FUNCTIONINTMASK: u32 = SDIO_FUNC_ENABLE_2 as u32;
const HMB_DATA_NAKHANDLED: u32 = 0x0001;
const HMB_DATA_DEVREADY: u32 = 0x0002;
const HMB_DATA_FC: u32 = 0x0004;
const HMB_DATA_FWREADY: u32 = 0x0008;
const HMB_DATA_FWHALT: u32 = 0x0010;
const HMB_DATA_VERSION_MASK: u32 = 0x00FF_0000;
const HMB_DATA_VERSION_SHIFT: u32 = 16;
const SDPCM_PROT_VERSION: u32 = 4;
const CY_43455_F2_WATERMARK: u8 = 0x60;
const CY_43455_MESBUSYCTRL: u8 = 0xD0;

const BACKPLANE_ADDRESS_MASK: u32 = 0x7FFF;
const BACKPLANE_WINDOW_MASK: u32 = 0xFFFF_8000;
const BACKPLANE_32BIT_FLAG: u32 = 0x8000;

const AI_IOCTRL_OFFSET: u32 = 0x408;
const AI_IOCTRL_BIT_FGC: u8 = 0x02;
const AI_IOCTRL_BIT_CLOCK_EN: u8 = 0x01;
const AI_RESETCTRL_OFFSET: u32 = 0x800;
const AI_RESETCTRL_BIT_RESET: u8 = 0x01;
const ARMCR4_BCMA_IOCTL_CPUHALT: u8 = 0x20;
const D11_BCMA_IOCTL_PHYCLOCKEN: u8 = 0x04;
const D11_BCMA_IOCTL_PHYRESET: u8 = 0x08;
const AI_CORE_PRERESET_IOCTRL: u8 = AI_IOCTRL_BIT_FGC | AI_IOCTRL_BIT_CLOCK_EN;
const AI_CORE_POSTRESET_IOCTRL: u8 = AI_IOCTRL_BIT_CLOCK_EN;
const ARMCR4_CAP: u32 = 0x0004;
const ARMCR4_BANKIDX: u32 = 0x0040;
const ARMCR4_BANKINFO: u32 = 0x0044;
const ARMCR4_BSZ_MASK: u32 = 0x7F;
const ARMCR4_BLK_1K_MASK: u32 = 0x200;
const ARMCR4_TCBANB_MASK: u32 = 0x0F;
const ARMCR4_TCBANB_SHIFT: u32 = 0;
const ARMCR4_TCBBNB_MASK: u32 = 0xF0;
const ARMCR4_TCBBNB_SHIFT: u32 = 4;
const ARMCR4_BSZ_MULT: u32 = 8192;

const CYW43_CHIPCOMMON_BASE: u32 = 0x1800_0000;
const CYW43_SDIO_CORE_BASE: u32 = 0x1800_4000;
const CYW43_D11_CORE_BASES: [u32; 1] = [0x1810_1000];
const CYW43_ARMCR4_CORE_BASE: u32 = 0x1810_3000;
const CYW43_SOCRAM_CORE_BASE: u32 = 0x1810_4000;
const CYW43_RAM_BASE_4345: u32 = 0x0019_8000;
const CYW43_RAM_SIZE_4345_PI4: u32 = 0x000c_8000;
const CYW43_FIRMWARE_RESET_VECTOR_ADDR: u32 = 0x0000_0000;
const CHIPCOMMON_PMUCONTROL_OFFSET: u32 = 0x600;
const CHIPCOMMON_PMUCONTROL_RES_RELOAD_VALUE: u32 = 0x2;
const CHIPCOMMON_PMUCONTROL_RES_SHIFT: u32 = 13;

#[inline]
const fn sdio_core_reg_addr(offset: u32) -> u32 {
    CYW43_SDIO_CORE_BASE + offset
}

#[inline]
const fn chipcommon_pmucontrol_addr() -> u32 {
    CYW43_CHIPCOMMON_BASE + CHIPCOMMON_PMUCONTROL_OFFSET
}

#[inline]
const fn chipcommon_pmucontrol_res_reload_bits() -> u32 {
    CHIPCOMMON_PMUCONTROL_RES_RELOAD_VALUE << CHIPCOMMON_PMUCONTROL_RES_SHIFT
}

#[inline]
const fn linux_probe_attach_uses_live_pmu_readback() -> bool {
    false
}

#[inline]
const fn linux_probe_attach_uses_live_iorx_readback() -> bool {
    false
}

#[inline]
const fn sdio_core_transfer_function_addr(offset: u32) -> u32 {
    backplane_word_function_addr(backplane_word_aligned_addr(sdio_core_reg_addr(offset)))
}

#[inline]
const fn sdio_core_byte_function_addr(offset: u32) -> u32 {
    backplane_byte_function_addr(sdio_core_reg_addr(offset))
}

#[inline]
const fn sdio_core_transfer_increment_addr() -> bool {
    true
}

#[inline]
const fn sdio_core_read_retries_backplane_word_path(offset: u32) -> bool {
    matches!(offset, SDIO_INT_STATUS | SDPCMD_REG_TOHOSTMAILBOXDATA)
}

#[inline]
const fn control_plane_snapshot_bit_state_label(value: Option<u8>, bit: u8) -> &'static str {
    match value {
        Some(bits) if (bits & bit) != 0 => "set",
        Some(_) => "clear",
        None => "unread",
    }
}

#[inline]
const fn control_plane_snapshot_match_label(value: Option<u32>, expected: u32) -> &'static str {
    match value {
        Some(bits) if bits == expected => "match",
        Some(_) => "diff",
        None => "unread",
    }
}

#[inline]
const fn control_plane_snapshot_u32_bit_state_label(value: Option<u32>, bit: u32) -> &'static str {
    match value {
        Some(bits) if (bits & bit) != 0 => "set",
        Some(_) => "clear",
        None => "unread",
    }
}

#[inline]
const fn control_plane_snapshot_reply_frame_label(
    low: Option<u8>,
    high: Option<u8>,
) -> &'static str {
    if low.is_some() && high.is_some() {
        "seen"
    } else {
        "miss"
    }
}

#[inline]
const fn control_plane_snapshot_hint_visibility_label(visible: usize) -> &'static str {
    match visible {
        0 => "none",
        4 => "full",
        _ => "part",
    }
}

#[inline]
const fn control_plane_function2_enable_latched_not_ready(
    ioex: Option<u8>,
    iorx: Option<u8>,
) -> bool {
    let f2_enable_bit = SDIO_FUNCTION_ENABLE_F2.enable_bit;
    matches!(ioex, Some(bits) if (bits & f2_enable_bit) != 0)
        && matches!(iorx, Some(bits) if (bits & f2_enable_bit) == 0)
}

#[inline]
const fn control_plane_function2_interrupts_armed(ienx: Option<u8>) -> bool {
    matches!(ienx, Some(bits) if (bits & SDIO_INTERRUPT_ENABLE_MASK) == SDIO_INTERRUPT_ENABLE_MASK)
}

#[inline]
const fn control_plane_function2_corecontrol_ready(corecontrol: Option<u32>) -> bool {
    matches!(corecontrol, Some(bits) if (bits & CC_F2RDY) != 0)
}

#[inline]
const fn control_plane_function2_ready_hidden_from_cccr(
    ioex: Option<u8>,
    iorx: Option<u8>,
    corecontrol: Option<u32>,
) -> bool {
    control_plane_function2_enable_latched_not_ready(ioex, iorx)
        && control_plane_function2_corecontrol_ready(corecontrol)
}

#[inline]
const fn control_plane_function2_linux_transport_configured(
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
) -> bool {
    matches!(watermark, Some(value) if value == CY_43455_F2_WATERMARK)
        && matches!(devctl, Some(bits) if (bits & SBSDIO_DEVCTL_F2WM_ENAB) != 0)
        && matches!(mesbusy, Some(value) if value == CY_43455_MESBUSYCTRL)
}

#[inline]
const fn control_plane_function2_linux_minimal_configured(
    ienx: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
) -> bool {
    control_plane_function2_interrupts_armed(ienx)
        && control_plane_function2_linux_transport_configured(watermark, devctl, mesbusy)
}

#[inline]
const fn control_plane_function2_latched_linux_configured_without_iorx(
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
) -> bool {
    control_plane_function2_enable_latched_not_ready(ioex, iorx)
        && control_plane_function2_interrupts_armed(ienx)
        && control_plane_function2_linux_transport_configured(watermark, devctl, mesbusy)
}

#[inline]
const fn post_firmware_ready_function2_strict_repoll_can_soft_continue(
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
) -> bool {
    control_plane_function2_latched_linux_configured_without_iorx(
        ioex, iorx, ienx, watermark, devctl, mesbusy,
    )
}

#[inline]
fn post_firmware_ready_function2_strict_repoll_prefers_fail_fast(
    experimental_no_ht_transport: bool,
    exact_error: &'static str,
) -> bool {
    experimental_no_ht_transport && control_plane_exact_error_is_first_reply_blocker(exact_error)
}

#[inline]
fn post_firmware_ready_function2_strict_repoll_prefers_direct_reply_probe_cutover(
    experimental_no_ht_transport: bool,
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
    exact_error: &'static str,
) -> bool {
    experimental_no_ht_transport
        && control_plane_function2_latched_linux_configured_without_iorx(
            ioex, iorx, ienx, watermark, devctl, mesbusy,
        )
        && control_plane_exact_error_is_first_reply_blocker(exact_error)
}

#[inline]
fn post_firmware_ready_function2_strict_repoll_prefers_cached_direct_reply_probe_cutover(
    experimental_no_ht_transport: bool,
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
    cached_snapshot: Option<&WifiDebugSnapshot>,
) -> bool {
    experimental_no_ht_transport
        && control_plane_function2_latched_linux_configured_without_iorx(
            ioex, iorx, ienx, watermark, devctl, mesbusy,
        )
        && cached_snapshot
            .is_some_and(cached_first_reply_blocker_prefers_direct_reply_probe_cutover)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Function2StrictRepollRecovery {
    FailFast,
    CutoverToBoundedNoHtReplyProbe,
}

#[inline]
const fn post_firmware_ready_function2_strict_repoll_recovery(
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
) -> Function2StrictRepollRecovery {
    if post_firmware_ready_function2_strict_repoll_can_soft_continue(
        ioex, iorx, ienx, watermark, devctl, mesbusy,
    ) {
        Function2StrictRepollRecovery::CutoverToBoundedNoHtReplyProbe
    } else {
        Function2StrictRepollRecovery::FailFast
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StrictControlPlaneReplyRecoveryAction {
    FailFast,
    ResumeBoundedNoHtReplyProbe,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PassiveStartupLinkTimeoutAction {
    Fail(&'static str),
    ResumeBoundedNoHtReplyProbe(&'static str),
}

#[inline]
fn strict_control_plane_reply_recovery_action(
    exact_error: &'static str,
) -> StrictControlPlaneReplyRecoveryAction {
    if exact_error == "cyw43-control-plane-sideband-unreadable"
        || exact_error.starts_with("cyw43-control-plane-sideband-")
        || exact_error.starts_with("cyw43-function2-reply-")
        || exact_error.starts_with("cyw43-function2-enable-latched-not-ready-sideband-")
        || exact_error == "cyw43-control-plane-no-reply-linux-f2-armed"
    {
        StrictControlPlaneReplyRecoveryAction::ResumeBoundedNoHtReplyProbe
    } else {
        StrictControlPlaneReplyRecoveryAction::FailFast
    }
}

#[inline]
const fn control_plane_function2_linux_state_label(
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
) -> &'static str {
    if control_plane_function2_enable_latched_not_ready(ioex, iorx)
        && control_plane_function2_linux_transport_configured(watermark, devctl, mesbusy)
        && !control_plane_function2_interrupts_armed(ienx)
    {
        "latched-linux-transport-no-iorx"
    } else if control_plane_function2_latched_linux_configured_without_iorx(
        ioex, iorx, ienx, watermark, devctl, mesbusy,
    ) {
        "latched-linux-configured-no-iorx"
    } else if control_plane_function2_linux_transport_configured(watermark, devctl, mesbusy)
        && !control_plane_function2_interrupts_armed(ienx)
    {
        "linux-transport-configured"
    } else if control_plane_function2_enable_latched_not_ready(ioex, iorx) {
        "latched-no-iorx"
    } else if control_plane_function2_linux_minimal_configured(ienx, watermark, devctl, mesbusy) {
        "linux-configured"
    } else {
        "unproven"
    }
}

#[inline]
const fn control_plane_snapshot_interrupts_deferred(
    ienx: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
) -> bool {
    !control_plane_function2_interrupts_armed(ienx)
        && control_plane_function2_linux_transport_configured(watermark, devctl, mesbusy)
}

#[inline]
const fn control_plane_snapshot_exact_blocker_label(
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    corecontrol: Option<u32>,
    hint_visible: usize,
    hostintmask: Option<u32>,
    function_int_mask: Option<u32>,
    low: Option<u8>,
    high: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
) -> &'static str {
    let f2_enable_bit = SDIO_FUNCTION_ENABLE_F2.enable_bit;
    if matches!(ioex, Some(bits) if (bits & f2_enable_bit) == 0) {
        "f2-disabled"
    } else if control_plane_function2_ready_hidden_from_cccr(ioex, iorx, corecontrol) {
        "f2-ready-hidden-from-cccr"
    } else if hint_visible == 0 && (low.is_none() || high.is_none()) {
        "sdio-core-hints-unreadable"
    } else if matches!(ioex, Some(bits) if (bits & f2_enable_bit) != 0) && iorx.is_none() {
        "f2-ready-unreadable"
    } else if control_plane_function2_enable_latched_not_ready(ioex, iorx) {
        "f2-enable-latched-not-ready"
    } else if control_plane_snapshot_interrupts_deferred(ienx, watermark, devctl, mesbusy) {
        "linux-configured-interrupts-deferred"
    } else if ienx.is_some() && !control_plane_function2_interrupts_armed(ienx) {
        "f2-interrupt-gated"
    } else if ienx.is_none() {
        "f2-interrupt-unreadable"
    } else if matches!(hostintmask, Some(bits) if bits != HOSTINTMASK)
        || matches!(function_int_mask, Some(bits) if bits != FUNCTIONINTMASK)
    {
        "interrupt-programming-drift"
    } else if low.is_none() || high.is_none() {
        "reply-frame-missing"
    } else if hint_visible != 4 {
        "partial-hint-visibility"
    } else {
        "state-visible"
    }
}

#[inline]
const fn passive_startup_link_timeout_error(
    ioex: Option<u8>,
    iorx: Option<u8>,
    corecontrol: Option<u32>,
) -> &'static str {
    if control_plane_function2_ready_hidden_from_cccr(ioex, iorx, corecontrol) {
        "cyw43-function2-ready-hidden-from-cccr"
    } else if control_plane_function2_enable_latched_not_ready(ioex, iorx) {
        "cyw43-function2-enable-latched-not-ready"
    } else {
        "cyw43-control-plane-passive-startup-link-timeout"
    }
}

#[inline]
fn strict_control_plane_reply_recovery_error(
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    corecontrol: Option<u32>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
    sdhci_read_diag: &'static str,
) -> Option<&'static str> {
    if control_plane_function2_ready_hidden_from_cccr(ioex, iorx, corecontrol) {
        Some("cyw43-function2-ready-hidden-from-cccr")
    } else if control_plane_function2_latched_linux_configured_without_iorx(
        ioex, iorx, ienx, watermark, devctl, mesbusy,
    ) && corecontrol.is_none()
    {
        Some(control_plane_snapshot_exact_error_label_with_sdhci_diag(
            "f2-enable-latched-not-ready",
            sdhci_read_diag,
        ))
    } else if control_plane_function2_latched_linux_configured_without_iorx(
        ioex, iorx, ienx, watermark, devctl, mesbusy,
    ) {
        Some(control_plane_snapshot_exact_error_label_with_sdhci_diag(
            "f2-enable-latched-not-ready",
            sdhci_read_diag,
        ))
    } else {
        None
    }
}

#[inline]
fn passive_startup_link_timeout_action(
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    corecontrol: Option<u32>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
    sdhci_read_diag: &'static str,
) -> PassiveStartupLinkTimeoutAction {
    if let Some(exact_error) = strict_control_plane_reply_recovery_error(
        ioex,
        iorx,
        ienx,
        corecontrol,
        watermark,
        devctl,
        mesbusy,
        sdhci_read_diag,
    ) {
        if matches!(
            strict_control_plane_reply_recovery_action(exact_error),
            StrictControlPlaneReplyRecoveryAction::ResumeBoundedNoHtReplyProbe
        ) {
            PassiveStartupLinkTimeoutAction::ResumeBoundedNoHtReplyProbe(exact_error)
        } else {
            PassiveStartupLinkTimeoutAction::Fail(exact_error)
        }
    } else if control_plane_function2_latched_linux_configured_without_iorx(
        ioex, iorx, ienx, watermark, devctl, mesbusy,
    ) {
        PassiveStartupLinkTimeoutAction::Fail("cyw43-control-plane-no-reply-linux-f2-armed")
    } else {
        PassiveStartupLinkTimeoutAction::Fail(passive_startup_link_timeout_error(
            ioex,
            iorx,
            corecontrol,
        ))
    }
}

#[inline]
fn resolved_control_plane_sdhci_read_diag(
    current_cmd: Option<u16>,
    current_arg: Option<u32>,
    current_present: Option<u32>,
    current_status: Option<u32>,
    preserved_cmd: Option<u16>,
    preserved_arg: Option<u32>,
    preserved_present: Option<u32>,
    preserved_status: Option<u32>,
) -> &'static str {
    let current = control_plane_snapshot_sdhci_read_diag_label(
        current_cmd,
        current_arg,
        current_present,
        current_status,
    );
    if current != "none" {
        return current;
    }
    control_plane_snapshot_sdhci_read_diag_label(
        preserved_cmd,
        preserved_arg,
        preserved_present,
        preserved_status,
    )
}

#[inline]
fn control_plane_reply_retry_effective_sdhci_read_diag(
    current_cmd: Option<u16>,
    current_arg: Option<u32>,
    current_present: Option<u32>,
    current_status: Option<u32>,
    preserved_cmd: Option<u16>,
    preserved_arg: Option<u32>,
    preserved_present: Option<u32>,
    preserved_status: Option<u32>,
    cached_sdhci_read_diag: Option<&'static str>,
) -> Option<&'static str> {
    let resolved = resolved_control_plane_sdhci_read_diag(
        current_cmd,
        current_arg,
        current_present,
        current_status,
        preserved_cmd,
        preserved_arg,
        preserved_present,
        preserved_status,
    );
    if resolved != "none" {
        return Some(resolved);
    }
    cached_sdhci_read_diag.filter(|diag| *diag != "none")
}

#[inline]
fn preserve_cached_first_reply_blocker_in_snapshot(
    mut snapshot: WifiDebugSnapshot,
    cached: &WifiDebugSnapshot,
) -> WifiDebugSnapshot {
    let snapshot_is_same_startup_link_first_reply_lane = matches!(
        snapshot.control_plane_bootstrap_phase,
        "startup-link-recovery" | "first-write-startup-link"
    ) && matches!(
        snapshot.control_plane_f2_state,
        "latched-linux-configured-no-iorx" | "latched-no-iorx"
    );
    let snapshot_is_same_first_reply_recovery = snapshot_is_same_startup_link_first_reply_lane
        && control_plane_frame_recovery_stage_is_first_reply_recovery(
            snapshot.control_plane_frame_recovery_stage,
        );
    let cached_is_specific_first_reply_blocker = matches!(
        cached.control_plane_exact_error,
        reason
            if reason.starts_with("cyw43-function2-reply-")
                || reason.starts_with("cyw43-control-plane-sideband-")
                || reason.starts_with("cyw43-function2-enable-latched-not-ready-")
    );
    let snapshot_is_specific_but_weaker_than_cached_direct_reply = cached
        .control_plane_exact_error
        .starts_with("cyw43-function2-reply-")
        && snapshot_is_same_first_reply_recovery
        && matches!(
            snapshot.control_plane_exact_error,
            reason
                if reason.starts_with("cyw43-control-plane-sideband-")
                    || reason.starts_with("cyw43-function2-enable-latched-not-ready")
        );
    let snapshot_is_specific_but_weaker_than_cached_enable_latch = cached
        .control_plane_exact_error
        .starts_with("cyw43-function2-enable-latched-not-ready")
        && snapshot_is_same_startup_link_first_reply_lane
        && matches!(
            snapshot.control_plane_exact_error,
            "cyw43-control-plane-sideband-read-stall-no-buffer-ready"
                | "cyw43-function2-enable-latched-not-ready-sideband-read-stall-no-buffer-ready"
        );
    let snapshot_is_weaker_first_reply_result =
        control_plane_exact_error_is_generic_no_reply(snapshot.control_plane_exact_error)
            || snapshot_is_specific_but_weaker_than_cached_direct_reply
            || snapshot_is_specific_but_weaker_than_cached_enable_latch
            || (control_plane_exact_error_is_first_reply_blocker(
                snapshot.control_plane_exact_error,
            ) && !matches!(
                snapshot.control_plane_exact_error,
                reason
                    if reason.starts_with("cyw43-function2-reply-")
                        || reason.starts_with("cyw43-control-plane-sideband-")
                        || reason.starts_with("cyw43-function2-enable-latched-not-ready-")
            ));
    let snapshot_f2_state_degraded_from_cached_linux_configured = cached.control_plane_f2_state
        == "latched-linux-configured-no-iorx"
        && snapshot.control_plane_f2_state == "latched-no-iorx";
    let same_first_reply_blocker_family =
        control_plane_exact_error_is_first_reply_blocker(cached.control_plane_exact_error)
            && control_plane_exact_error_is_first_reply_blocker(snapshot.control_plane_exact_error);
    let same_direct_reply_blocker = cached
        .control_plane_exact_error
        .starts_with("cyw43-function2-reply-")
        && snapshot.control_plane_exact_error == cached.control_plane_exact_error;

    if control_plane_exact_error_is_pre_function2_clock_blocker(cached.control_plane_exact_error)
        && matches!(
            snapshot.control_plane_exact_error,
            "cyw43-function2-disabled"
                | "cyw43-function2-enable-latched-not-ready"
                | "cyw43-function2-enable-latched-not-ready-sideband-read-stall-no-buffer-ready"
                | "sdio-function2-ready-timeout"
        )
    {
        snapshot.control_plane_exact_error = cached.control_plane_exact_error;
        if cached.control_plane_sdhci_read_diag != "none" {
            snapshot.control_plane_sdhci_read_diag = cached.control_plane_sdhci_read_diag;
        }
        if cached.control_plane_f2_state != "unproven" {
            snapshot.control_plane_f2_state = cached.control_plane_f2_state;
        }
    }

    if control_plane_exact_error_is_first_reply_blocker(cached.control_plane_exact_error)
        && (control_plane_exact_error_is_generic_no_reply(snapshot.control_plane_exact_error)
            || (cached_is_specific_first_reply_blocker
                && snapshot_is_same_startup_link_first_reply_lane
                && snapshot_is_weaker_first_reply_result))
    {
        snapshot.control_plane_exact_error = cached.control_plane_exact_error;
        if cached.control_plane_sdhci_read_diag != "none" {
            snapshot.control_plane_sdhci_read_diag = cached.control_plane_sdhci_read_diag;
        }
        if snapshot_f2_state_degraded_from_cached_linux_configured
            && (snapshot_is_same_first_reply_recovery
                || same_direct_reply_blocker
                || (snapshot_is_same_startup_link_first_reply_lane
                    && cached_first_reply_blocker_preserves_linux_configured_f2_state(cached)))
        {
            snapshot.control_plane_f2_state = cached.control_plane_f2_state;
        }
    }
    if snapshot_f2_state_degraded_from_cached_linux_configured
        && (same_direct_reply_blocker
            || (snapshot_is_same_first_reply_recovery && same_first_reply_blocker_family)
            || (snapshot_is_same_startup_link_first_reply_lane
                && cached_first_reply_blocker_preserves_linux_configured_f2_state(cached)
                && matches!(
                    snapshot.control_plane_exact_error,
                    reason
                        if reason.starts_with("cyw43-control-plane-sideband-")
                            || reason.starts_with("cyw43-function2-enable-latched-not-ready")
                )))
    {
        snapshot.control_plane_f2_state = cached.control_plane_f2_state;
        if same_direct_reply_blocker && cached.control_plane_sdhci_read_diag != "none" {
            snapshot.control_plane_sdhci_read_diag = cached.control_plane_sdhci_read_diag;
        }
    }
    snapshot
}

#[inline]
fn cached_first_reply_blocker_preserves_linux_configured_f2_state(
    cached: &WifiDebugSnapshot,
) -> bool {
    cached.control_plane_no_ht_transport
        && matches!(
            cached.control_plane_bootstrap_phase,
            "startup-link-recovery" | "startup-link-passive-wait" | "first-write-startup-link"
        )
        && cached.control_plane_f2_state == "latched-linux-configured-no-iorx"
        && control_plane_exact_error_is_first_reply_blocker(cached.control_plane_exact_error)
}

#[inline]
fn should_preserve_function2_enable_latch_from_cached_first_reply_blocker(
    ioex: Option<u8>,
    iorx: Option<u8>,
    hint_reads_unstable: bool,
    cached: Option<&WifiDebugSnapshot>,
) -> bool {
    hint_reads_unstable
        && control_plane_function2_enable_latched_not_ready(ioex, iorx)
        && cached.is_some_and(cached_first_reply_blocker_preserves_linux_configured_f2_state)
}

#[inline]
fn effective_control_plane_snapshot_f2_linux_state(
    ioex: Option<u8>,
    iorx: Option<u8>,
    ienx: Option<u8>,
    watermark: Option<u8>,
    devctl: Option<u8>,
    mesbusy: Option<u8>,
    hint_reads_unstable: bool,
    cached: Option<&WifiDebugSnapshot>,
) -> (&'static str, bool, bool) {
    if watermark.is_none()
        && devctl.is_none()
        && mesbusy.is_none()
        && should_preserve_function2_enable_latch_from_cached_first_reply_blocker(
            ioex,
            iorx,
            hint_reads_unstable,
            cached,
        )
    {
        return ("latched-linux-configured-no-iorx", true, true);
    }

    (
        control_plane_function2_linux_state_label(ioex, iorx, ienx, watermark, devctl, mesbusy),
        control_plane_function2_linux_transport_configured(watermark, devctl, mesbusy),
        control_plane_function2_latched_linux_configured_without_iorx(
            ioex, iorx, ienx, watermark, devctl, mesbusy,
        ),
    )
}

#[inline]
fn cache_wifi_debug_snapshot(snapshot: WifiDebugSnapshot) {
    let mut last_snapshot = LAST_WIFI_DEBUG_SNAPSHOT.lock();
    if let Some(cached) = last_snapshot.as_ref() {
        if should_use_cached_wifi_debug_snapshot(&snapshot, cached) {
            return;
        }
    }
    let snapshot = if let Some(cached) = last_snapshot.as_ref() {
        preserve_cached_first_reply_blocker_in_snapshot(snapshot, cached)
    } else {
        snapshot
    };
    *last_snapshot = Some(snapshot);
}

#[inline]
fn cache_wifi_debug_snapshot_if_informative(snapshot: WifiDebugSnapshot) {
    if wifi_debug_snapshot_should_be_cached(&snapshot) {
        cache_wifi_debug_snapshot(snapshot);
    }
}

#[inline]
fn cached_wifi_debug_snapshot() -> Option<WifiDebugSnapshot> {
    LAST_WIFI_DEBUG_SNAPSHOT.lock().as_ref().copied()
}

#[inline]
fn cache_wifi_firmware_contract_evidence(evidence: WifiFirmwareContractEvidence) {
    *LAST_WIFI_FIRMWARE_CONTRACT_EVIDENCE.lock() = Some(evidence);
}

#[inline]
fn cached_wifi_firmware_contract_evidence() -> Option<WifiFirmwareContractEvidence> {
    LAST_WIFI_FIRMWARE_CONTRACT_EVIDENCE
        .lock()
        .as_ref()
        .copied()
}

#[inline]
fn cache_wifi_firmware_proof(proof: WifiFirmwareProofTrace) {
    *LAST_WIFI_FIRMWARE_PROOF.lock() = Some(proof);
}

#[inline]
fn cached_wifi_firmware_proof() -> Option<WifiFirmwareProofTrace> {
    LAST_WIFI_FIRMWARE_PROOF.lock().as_ref().copied()
}

#[inline]
fn cache_wifi_ht_phase_record(record: WifiHtPhaseRecord) {
    LAST_WIFI_HT_PHASES.lock().push(record);
}

#[inline]
fn cached_wifi_ht_phase_records() -> ([WifiHtPhaseRecord; WIFI_HT_PHASE_RECORD_CAPACITY], u8) {
    LAST_WIFI_HT_PHASES.lock().ordered()
}

#[inline]
fn cache_wifi_bounded_phase_record(record: WifiBoundedPhaseRecord) {
    LAST_WIFI_BOUNDED_PHASES.lock().push(record);
}

#[inline]
fn cached_wifi_bounded_phase_records() -> (
    [WifiBoundedPhaseRecord; WIFI_BOUNDED_PHASE_RECORD_CAPACITY],
    u8,
) {
    LAST_WIFI_BOUNDED_PHASES.lock().ordered()
}

#[inline]
fn firmware_contract_should_use_cached_snapshot(
    live_card_ready: bool,
    live_armcr4_release_attempts: u8,
    cached_snapshot: &WifiDebugSnapshot,
    cached_evidence: WifiFirmwareContractEvidence,
) -> bool {
    !live_card_ready
        && cached_snapshot.card_ready
        && cached_evidence.armcr4_release_attempts > live_armcr4_release_attempts
        && control_plane_exact_error_is_pre_function2_clock_blocker(
            cached_snapshot.control_plane_exact_error,
        )
}

#[inline]
fn wifi_debug_snapshot_should_be_cached(snapshot: &WifiDebugSnapshot) -> bool {
    let has_live_transport_evidence = snapshot.card_ready
        || snapshot.io_enable.is_some()
        || snapshot.io_ready.is_some()
        || snapshot.chipclkcsr.is_some()
        || snapshot.shadow_backplane_window.is_some();
    snapshot.control_plane_f2_state != "unproven"
        || snapshot.control_plane_startup_profile_locked
        || snapshot.debug_snapshot_stage.ends_with("-fail")
        || (has_live_transport_evidence
            && control_plane_exact_error_is_more_informative(snapshot.control_plane_exact_error))
}

#[inline]
fn promote_cached_wifi_debug_snapshot_exact_error(exact_error: &'static str) {
    if !exact_error.starts_with("cyw43-function2-reply-") {
        return;
    }

    let mut last_snapshot = LAST_WIFI_DEBUG_SNAPSHOT.lock();
    let Some(snapshot) = last_snapshot.as_mut() else {
        return;
    };

    snapshot.control_plane_exact_error = exact_error;
    let promoted_diag = control_plane_direct_reply_exact_error_sdhci_read_diag(exact_error);
    if promoted_diag != "none" {
        snapshot.control_plane_sdhci_read_diag = promoted_diag;
    }
    if snapshot.control_plane_no_ht_transport
        && snapshot.control_plane_bootstrap_phase == "startup-link-recovery"
        && snapshot.control_plane_f2_state == "latched-no-iorx"
        && control_plane_frame_recovery_stage_is_first_reply_recovery(
            snapshot.control_plane_frame_recovery_stage,
        )
        && matches!(
            snapshot.control_plane_exact_error,
            reason
                if reason.starts_with("cyw43-function2-reply-")
                    || reason.starts_with("cyw43-control-plane-sideband-")
                    || reason.starts_with("cyw43-function2-enable-latched-not-ready")
        )
    {
        snapshot.control_plane_f2_state = "latched-linux-configured-no-iorx";
    }
}

#[inline]
fn cached_wifi_debug_snapshot_is_more_informative(snapshot: &WifiDebugSnapshot) -> bool {
    snapshot.card_ready
        || snapshot.debug_snapshot_stage.ends_with("-fail")
        || snapshot.control_plane_no_ht_transport
        || snapshot.control_plane_f2_state != "unproven"
        || snapshot.control_plane_startup_profile_locked
        || control_plane_exact_error_is_more_informative(snapshot.control_plane_exact_error)
}

#[inline]
fn should_use_cached_wifi_debug_snapshot(
    live: &WifiDebugSnapshot,
    cached: &WifiDebugSnapshot,
) -> bool {
    let live_is_boot_dead = !live.card_ready && live.control_plane_f2_state == "unproven";
    let live_is_generic_no_reply =
        control_plane_exact_error_is_generic_no_reply(live.control_plane_exact_error)
            && control_plane_exact_error_is_first_reply_blocker(cached.control_plane_exact_error);
    let live_is_blank_first_reply_recovery =
        control_plane_exact_error_is_first_reply_blocker(cached.control_plane_exact_error)
            && control_plane_exact_error_is_generic_no_reply(live.control_plane_exact_error)
            && live.control_plane_bootstrap_phase == "startup-link-recovery"
            && control_plane_frame_recovery_stage_is_first_reply_recovery(
                live.control_plane_frame_recovery_stage,
            )
            && matches!(
                live.control_plane_f2_state,
                "latched-linux-configured-no-iorx" | "latched-no-iorx"
            );
    let live_is_weaker_startup_link_sideband =
        cached_first_reply_blocker_preserves_linux_configured_f2_state(cached)
            && live.control_plane_bootstrap_phase == "startup-link-recovery"
            && (control_plane_frame_recovery_stage_is_first_reply_recovery(
                live.control_plane_frame_recovery_stage,
            ) || live.control_plane_frame_recovery_stage.is_none())
            && live.control_plane_exact_error
                == "cyw43-control-plane-sideband-read-stall-no-buffer-ready"
            && matches!(
                live.control_plane_f2_state,
                "latched-linux-configured-no-iorx" | "latched-no-iorx"
            );
    let live_is_less_informative_sideband = (!live.control_plane_no_ht_transport
        || (live.control_plane_startup_link_stable
            && live.control_plane_bootstrap_phase == "startup-link-passive-wait"
            && control_plane_exact_error_is_first_reply_blocker(cached.control_plane_exact_error)))
        && live.control_plane_exact_error
            != "cyw43-control-plane-sideband-read-stall-no-buffer-ready"
        && (live
            .control_plane_exact_error
            .starts_with("cyw43-control-plane-sideband-")
            || live.control_plane_exact_error == "cyw43-control-plane-sideband-unreadable");

    (live_is_boot_dead
        || live_is_generic_no_reply
        || live_is_blank_first_reply_recovery
        || live_is_weaker_startup_link_sideband
        || live_is_less_informative_sideband)
        && cached_wifi_debug_snapshot_is_more_informative(cached)
}

#[inline]
fn control_plane_snapshot_exact_error_label(blocker: &'static str) -> &'static str {
    match blocker {
        "f2-disabled" => "cyw43-function2-disabled",
        "f2-ready-hidden-from-cccr" => "cyw43-function2-ready-hidden-from-cccr",
        "f2-enable-latched-not-ready" => "cyw43-function2-enable-latched-not-ready",
        "f2-ready-unreadable" => "cyw43-function2-ready-unreadable",
        "linux-configured-interrupts-deferred" => "cyw43-control-plane-linux-interrupts-deferred",
        "f2-interrupt-gated" => "cyw43-function2-interrupt-gated",
        "f2-interrupt-unreadable" => "cyw43-function2-interrupt-unreadable",
        "sdio-core-hints-unreadable" => "cyw43-control-plane-sideband-unreadable",
        "interrupt-programming-drift" => "cyw43-control-plane-interrupt-programming-drift",
        "reply-frame-missing" => "cyw43-control-plane-reply-frame-missing",
        "partial-hint-visibility" => "cyw43-control-plane-partial-hint-visibility",
        _ => "cyw43-control-plane-state-visible-no-reply",
    }
}

#[inline]
const fn sdio_cmd53_arg_is_write(arg: u32) -> bool {
    (arg & (1 << 31)) != 0
}

#[inline]
const fn sdio_cmd53_arg_function(arg: u32) -> u8 {
    ((arg >> 28) & 0x7) as u8
}

#[inline]
const fn sdio_cmd53_arg_increment_addr(arg: u32) -> bool {
    (arg & (1 << 26)) != 0
}

#[inline]
const fn sdio_cmd53_arg_addr(arg: u32) -> u32 {
    (arg >> 9) & 0x1_FFFF
}

#[inline]
const fn control_plane_reply_reg_function_addr_matches(addr: u32) -> bool {
    matches!(
        addr,
        a if a == sdio_core_transfer_function_addr(SDIO_INT_STATUS)
            || a == sdio_core_transfer_function_addr(SDPCMD_REG_HOSTINTMASK)
            || a == sdio_core_transfer_function_addr(SDPCMD_REG_FUNCTIONINTMASK)
            || a == sdio_core_transfer_function_addr(SDPCMD_REG_TOHOSTMAILBOXDATA)
            || a == sdio_core_byte_function_addr(SDIO_INT_STATUS)
            || a == sdio_core_byte_function_addr(SDPCMD_REG_HOSTINTMASK)
            || a == sdio_core_byte_function_addr(SDPCMD_REG_FUNCTIONINTMASK)
            || a == sdio_core_byte_function_addr(SDPCMD_REG_TOHOSTMAILBOXDATA)
    )
}

#[inline]
const fn control_plane_reply_reg_cmd53_read_matches(cmd: u16, arg: u32) -> bool {
    cmd == SDIO_CMD53
        && !sdio_cmd53_arg_is_write(arg)
        && sdio_cmd53_arg_function(arg) == SdioFunction::Function1.number()
        && control_plane_reply_reg_function_addr_matches(sdio_cmd53_arg_addr(arg))
}

#[inline]
const fn control_plane_reply_fifo_cmd53_read_matches(cmd: u16, arg: u32) -> bool {
    cmd == SDIO_CMD53
        && !sdio_cmd53_arg_is_write(arg)
        && !sdio_cmd53_arg_increment_addr(arg)
        && sdio_cmd53_arg_function(arg) == SdioFunction::Function2.number()
        && (sdio_cmd53_arg_addr(arg) == control_plane_function2_port_addr()
            || sdio_cmd53_arg_addr(arg) == 0)
}

#[inline]
const fn control_plane_snapshot_sdhci_read_diag_label(
    cmd: Option<u16>,
    arg: Option<u32>,
    present: Option<u32>,
    int_status: Option<u32>,
) -> &'static str {
    match (cmd, arg, present, int_status) {
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_fifo_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_TIMEOUT) != 0 =>
        {
            "f2-reply-read-command-timeout"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_fifo_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_CRC) != 0 =>
        {
            "f2-reply-read-command-crc"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_fifo_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_END_BIT) != 0 =>
        {
            "f2-reply-read-command-end-bit"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_fifo_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_INDEX) != 0 =>
        {
            "f2-reply-read-command-index"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_fifo_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_DATA_CRC) != 0 =>
        {
            "f2-reply-read-data-crc"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_fifo_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_DATA_END_BIT) != 0 =>
        {
            "f2-reply-read-data-end-bit"
        }
        (Some(SDIO_CMD53), Some(arg), Some(present), Some(0))
            if control_plane_reply_fifo_cmd53_read_matches(SDIO_CMD53, arg)
                && (present & (SDHCI_DATA_INHIBIT | SDHCI_READ_TRANSFER_ACTIVE))
                    == (SDHCI_DATA_INHIBIT | SDHCI_READ_TRANSFER_ACTIVE)
                && (present & SDHCI_DAT_ACTIVE) == 0
                && (present & SDHCI_DATA_AVAILABLE) == 0 =>
        {
            "f2-reply-read-command-phase-no-data-active"
        }
        (Some(SDIO_CMD53), Some(arg), Some(present), Some(0))
            if control_plane_reply_fifo_cmd53_read_matches(SDIO_CMD53, arg)
                && (present
                    & (SDHCI_DATA_INHIBIT | SDHCI_DAT_ACTIVE | SDHCI_READ_TRANSFER_ACTIVE))
                    == (SDHCI_DATA_INHIBIT | SDHCI_DAT_ACTIVE | SDHCI_READ_TRANSFER_ACTIVE)
                && (present & SDHCI_DATA_AVAILABLE) == 0 =>
        {
            "f2-reply-read-stalled-no-buffer-ready"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_fifo_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_ERROR) != 0 =>
        {
            "f2-reply-read-command-error"
        }
        (Some(SDIO_CMD53), Some(arg), Some(present), Some(0))
            if control_plane_reply_reg_cmd53_read_matches(SDIO_CMD53, arg)
                && (present & (SDHCI_DATA_INHIBIT | SDHCI_READ_TRANSFER_ACTIVE))
                    == (SDHCI_DATA_INHIBIT | SDHCI_READ_TRANSFER_ACTIVE)
                && (present & SDHCI_DAT_ACTIVE) == 0
                && (present & SDHCI_DATA_AVAILABLE) == 0 =>
        {
            "f1-reply-read-command-phase-no-data-active"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_reg_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_TIMEOUT) != 0 =>
        {
            "f1-reply-read-command-timeout"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_reg_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_CRC) != 0 =>
        {
            "f1-reply-read-command-crc"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_reg_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_END_BIT) != 0 =>
        {
            "f1-reply-read-command-end-bit"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_reg_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_INDEX) != 0 =>
        {
            "f1-reply-read-command-index"
        }
        (Some(SDIO_CMD53), Some(arg), Some(present), Some(0))
            if control_plane_reply_reg_cmd53_read_matches(SDIO_CMD53, arg)
                && (present
                    & (SDHCI_DATA_INHIBIT | SDHCI_DAT_ACTIVE | SDHCI_READ_TRANSFER_ACTIVE))
                    == (SDHCI_DATA_INHIBIT | SDHCI_DAT_ACTIVE | SDHCI_READ_TRANSFER_ACTIVE)
                && (present & SDHCI_DATA_AVAILABLE) == 0 =>
        {
            "f1-reply-read-stalled-no-buffer-ready"
        }
        (Some(SDIO_CMD53), Some(arg), _, Some(status))
            if control_plane_reply_reg_cmd53_read_matches(SDIO_CMD53, arg)
                && (status & SDHCI_INT_ERROR) != 0 =>
        {
            "f1-reply-read-command-error"
        }
        _ => "none",
    }
}

#[inline]
fn control_plane_snapshot_exact_error_label_with_sdhci_diag(
    blocker: &'static str,
    sdhci_read_diag: &'static str,
) -> &'static str {
    match blocker {
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f2-reply-read-command-timeout" => {
            "cyw43-function2-reply-command-timeout"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f2-reply-read-command-crc" => {
            "cyw43-function2-reply-command-crc"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f2-reply-read-command-end-bit" => {
            "cyw43-function2-reply-command-end-bit"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f2-reply-read-command-index" => {
            "cyw43-function2-reply-command-index"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f2-reply-read-command-error" => {
            "cyw43-function2-reply-command-error"
        }
        "sdio-core-hints-unreadable"
            if sdhci_read_diag == "f2-reply-read-command-phase-no-data-active" =>
        {
            "cyw43-function2-reply-command-stall"
        }
        "sdio-core-hints-unreadable"
            if sdhci_read_diag == "f2-reply-read-stalled-no-buffer-ready" =>
        {
            "cyw43-function2-reply-read-stall-no-buffer-ready"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f2-reply-read-data-end-bit" => {
            "cyw43-function2-reply-data-end-bit"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f2-reply-read-data-crc" => {
            "cyw43-function2-reply-data-crc"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f2-reply-read-command-timeout" => {
            "cyw43-function2-enable-latched-not-ready-command-timeout"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f2-reply-read-command-crc" => {
            "cyw43-function2-enable-latched-not-ready-command-crc"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f2-reply-read-command-end-bit" => {
            "cyw43-function2-enable-latched-not-ready-command-end-bit"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f2-reply-read-command-index" => {
            "cyw43-function2-enable-latched-not-ready-command-index"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f2-reply-read-command-error" => {
            "cyw43-function2-enable-latched-not-ready-command-error"
        }
        "f2-enable-latched-not-ready"
            if sdhci_read_diag == "f2-reply-read-command-phase-no-data-active" =>
        {
            "cyw43-function2-enable-latched-not-ready-command-stall"
        }
        "f2-enable-latched-not-ready"
            if sdhci_read_diag == "f2-reply-read-stalled-no-buffer-ready" =>
        {
            "cyw43-function2-enable-latched-not-ready-read-stall-no-buffer-ready"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f2-reply-read-data-end-bit" => {
            "cyw43-function2-enable-latched-not-ready-data-end-bit"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f2-reply-read-data-crc" => {
            "cyw43-function2-enable-latched-not-ready-data-crc"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f1-reply-read-command-timeout" => {
            "cyw43-function2-enable-latched-not-ready-sideband-command-timeout"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f1-reply-read-command-crc" => {
            "cyw43-function2-enable-latched-not-ready-sideband-command-crc"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f1-reply-read-command-end-bit" => {
            "cyw43-function2-enable-latched-not-ready-sideband-command-end-bit"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f1-reply-read-command-index" => {
            "cyw43-function2-enable-latched-not-ready-sideband-command-index"
        }
        "f2-enable-latched-not-ready" if sdhci_read_diag == "f1-reply-read-command-error" => {
            "cyw43-function2-enable-latched-not-ready-sideband-command-error"
        }
        "f2-enable-latched-not-ready"
            if sdhci_read_diag == "f1-reply-read-command-phase-no-data-active" =>
        {
            "cyw43-function2-enable-latched-not-ready-sideband-command-stall"
        }
        "f2-enable-latched-not-ready"
            if sdhci_read_diag == "f1-reply-read-stalled-no-buffer-ready" =>
        {
            "cyw43-function2-enable-latched-not-ready-sideband-read-stall-no-buffer-ready"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f1-reply-read-command-timeout" => {
            "cyw43-control-plane-sideband-command-timeout"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f1-reply-read-command-crc" => {
            "cyw43-control-plane-sideband-command-crc"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f1-reply-read-command-end-bit" => {
            "cyw43-control-plane-sideband-command-end-bit"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f1-reply-read-command-index" => {
            "cyw43-control-plane-sideband-command-index"
        }
        "sdio-core-hints-unreadable" if sdhci_read_diag == "f1-reply-read-command-error" => {
            "cyw43-control-plane-sideband-command-error"
        }
        "sdio-core-hints-unreadable"
            if sdhci_read_diag == "f1-reply-read-command-phase-no-data-active" =>
        {
            "cyw43-control-plane-sideband-command-stall"
        }
        "sdio-core-hints-unreadable"
            if sdhci_read_diag == "f1-reply-read-stalled-no-buffer-ready" =>
        {
            "cyw43-control-plane-sideband-read-stall-no-buffer-ready"
        }
        _ => control_plane_snapshot_exact_error_label(blocker),
    }
}

#[inline]
const fn control_plane_snapshot_bootstrap_phase_label(
    experimental_no_ht_transport: bool,
    write_probe_pending: bool,
    startup_link_stabilized: bool,
    current_clock_hz: u32,
) -> &'static str {
    if !experimental_no_ht_transport {
        "steady-state"
    } else if startup_link_stabilized {
        "startup-link-passive-wait"
    } else if write_probe_pending {
        if current_clock_hz <= CYW43_STARTUP_CLOCK_HZ {
            "first-write-startup-link"
        } else {
            "first-write-promoted-link"
        }
    } else if current_clock_hz <= CYW43_STARTUP_CLOCK_HZ {
        "startup-link-recovery"
    } else {
        "promoted-link-recovery"
    }
}

const SDIO_INIT_WAIT_LOOPS: usize = 50_000;
const SDIO_HOST_RESET_LOOPS: usize = 50_000;
const SDIO_CLOCK_STABLE_LOOPS: usize = 50_000;
const SDIO_CMD_WAIT_LOOPS: usize = 200_000;
const SDIO_DATA_WAIT_LOOPS: usize = 200_000;
const SDIO_CARD_INIT_ATTEMPTS: usize = 2;
const SDHCI_POWER_OFF_SETTLE_LOOPS: usize = 500_000;
const SDHCI_POWER_READY_LOOPS: usize = 500_000;
const SDHCI_POWER_SETTLE_LOOPS: usize = 20_000_000;
const SDIO_CARD_INIT_RETRY_SETTLE_LOOPS: usize = 500_000;
const WIFI_POWER_SETTLE_LOOPS: usize = 500_000;
const WIFI_POWER_DROP_SETTLE_LOOPS: usize = 20_000_000;
const CYW43_ARMCR4_CONTROL_SETTLE_LOOPS: usize = 50_000;
const CYW43_CORE_CONTROL_SETTLE_LOOPS: usize = 500_000;
const CYW43_SOCRAM_CLEAR_RESET_PREWRITE_SETTLE_LOOPS: usize = 20_000_000;
const CYW43_SOCRAM_CLEAR_RESET_KEEPALIVE_CHUNK_LOOPS: usize = CYW43_CORE_CONTROL_SETTLE_LOOPS;
const CYW43_BACKPLANE_FORCE_ALP_SETTLE_LOOPS: usize = 4_000;
const CYW43_CORE_RESET_RETRY_LIMIT: usize = 50;
const SDHCI_WRITE_DELAY_LOOPS: usize = 256;
const SDHCI_WRITE_GAP_SPIN_LOOPS: usize = SDHCI_WRITE_DELAY_LOOPS * 32;
const CYW43_READY_LOOPS: usize = 1_000;
const CYW43_TRANSFER_CHUNK: usize = 256;
// Firmware upload is the dominant no-HT boot cost. CMD53 byte-mode encodes a
// 512-byte transfer as count=0, so use that full legal byte-mode ceiling here
// while keeping generic backplane transfers on their smaller established chunk.
const CYW43_FIRMWARE_TRANSFER_CHUNK: usize = SDIO_MAX_BYTE_MODE;
const CYW43_FIRMWARE_PROGRESS_INTERVAL: usize = 16 * 1024;
const BCM2711_SDIO_MAILBOX_CLOCK_HZ: u32 = 100_000_000;
const BCM2711_SDIO_EFFECTIVE_BASE_CLOCK_HZ: u32 = 250_000_000;
// Linux on the same Pi 4 requests 50 MHz for mmc1 high-speed 4-bit SDIO and
// reports an actual 41.666667 MHz link. Request the same high-speed target;
// the SDHCI divider and mailbox base clock determine the exact delivered rate.
const CYW43_FIRMWARE_BULK_CLOCK_HZ: u32 = 50_000_000;
const CYW43_FIRMWARE_NO_HT_BULK_CLOCK_HZ: u32 = 1_562_500;
const CYW43_STARTUP_CLOCK_HZ: u32 = 400_000;
const CYW43_CONTROL_PLANE_CLOCK_HZ: u32 = 50_000_000;
const CYW43_CONTROL_PLANE_PASSIVE_STARTUP_LINK_EMPTY_POLL_LIMIT: u8 = 4;
const CYW43_CONTROL_PLANE_SIDEBAND_UNREADABLE_RECOVERY_LIMIT: u8 = 2;
const CYW43_CONTROL_PLANE_STARTUP_LINK_RESCUE_LIMIT: u8 =
    super::control_plane_startup_link_rescue_limit();
const SDIO_MAX_BYTE_MODE: usize = 512;
const SDIO_TRANSFER_TRACE_INCREMENT_CHUNKS: usize = 2;
const CYW43_FIRMWARE_VERIFY_CHUNK: usize = SDIO_MAX_BYTE_MODE;
const CYW43_FIRMWARE_PROOF_CHUNK: usize = 64;
const CYW43_FIRMWARE_BOOT_READBACK_VERIFY_ENABLED: bool = false;
const CYW43_HT_CLOCK_INITIAL_WAIT_LOOPS: usize = 2_048;
const CYW43_HT_CLOCK_SOFT_WAIT_LOOPS: usize = 8_192;
// Linux brcmfmac polls CHIPCLKCSR for up to PMU_MAX_TRANSITION_DLY with
// 5-10 ms sleeps. Keep the same shape in no_std form: fewer live register
// reads than the older micro-poll and a materially longer settle between
// reads, so the firmware PLL gets Linux-scale wall time to report HT_AVAIL.
const CYW43_HT_CLOCK_LINUX_ACTIVE_WAIT_POLLS: usize = 160;
const CYW43_HT_CLOCK_LINUX_ACTIVE_SETTLE_LOOPS: usize = 8_000_000;
const CYW43_HT_CLOCK_LINUX_SDONLY_SETTLE_LOOPS: usize =
    CYW43_HT_CLOCK_LINUX_ACTIVE_SETTLE_LOOPS * 4;
const CYW43_HT_CLOCK_LINUX_ACTIVE_PROGRESS_POLLS: usize = 8;
const CYW43_HT_CLOCK_LINUX_ACTIVE_WAIT_LOOPS: usize = CYW43_HT_CLOCK_LINUX_ACTIVE_WAIT_POLLS;
const CYW43_HT_CLOCK_LADDER_HZ: [u32; 4] = [
    CYW43_FIRMWARE_BULK_CLOCK_HZ / 2,
    CYW43_FIRMWARE_BULK_CLOCK_HZ / 4,
    CYW43_FIRMWARE_NO_HT_BULK_CLOCK_HZ,
    CYW43_STARTUP_CLOCK_HZ,
];
const CYW43_KSO_AWAKE_WAIT_LOOPS: usize = SDIO_INIT_WAIT_LOOPS;
const CYW43_KSO_DEVICE_ON_WAIT_LOOPS: usize = SDIO_INIT_WAIT_LOOPS;
const CYW43_KSO_DEVICE_ON_PROGRESS_INTERVAL_LOOPS: usize = SDIO_INIT_WAIT_LOOPS / 4;
const CYW43_KSO_REWRITE_INTERVAL_LOOPS: usize = 512;
const CYW43_KSO_INITIAL_SETTLE_LOOPS: usize = CYW43_BACKPLANE_FORCE_ALP_SETTLE_LOOPS;
const CYW43_KSO_DEVON_CLEAR_SET_POLLS: usize = SDIO_FUNCTION_READY_POLLS_FUNCTION2_EXTENDED_STRICT;
const CYW43_KSO_DEVON_CLEAR_SET_SETTLE_LOOPS: usize = SDIO_FUNCTION_READY_SETTLE_LOOPS_FUNCTION2;
const CYW43_KSO_DEVON_PROGRESS_POLLS: usize = 32;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct FirmwareVerifyRetryProfile {
    clock_hz: u32,
    width: SdioBusWidth,
    prefer_byte_mode: bool,
}

const CYW43_FIRMWARE_VERIFY_RETRY_PROFILES: [FirmwareVerifyRetryProfile; 2] = [
    FirmwareVerifyRetryProfile {
        clock_hz: CYW43_STARTUP_CLOCK_HZ,
        width: SdioBusWidth::FourBit,
        prefer_byte_mode: true,
    },
    FirmwareVerifyRetryProfile {
        clock_hz: CYW43_STARTUP_CLOCK_HZ,
        width: SdioBusWidth::OneBit,
        prefer_byte_mode: true,
    },
];

#[inline]
fn spin_wifi_progress_loops(loops: usize) {
    for _ in 0..loops {
        spin_loop();
    }
    wifi_progress_advance_loops(loops);
}

