    #[test]
    fn firmware_release_contract_reports_real_ht_prerequisites() {
        assert_eq!(
            firmware_release_contract_blocker(false, None, false, 0, None),
            "sdio-card-not-ready"
        );
        assert_eq!(
            firmware_release_contract_blocker(true, None, false, 0, None),
            "firmware-reset-vector-missing"
        );
        assert_eq!(
            firmware_release_contract_blocker(true, Some(0x1234_5678), false, 0, None),
            "armcr4-release-not-attempted"
        );
        assert_eq!(
            firmware_release_contract_blocker(true, Some(0x1234_5678), false, 1, None),
            "chipclkcsr-unreadable"
        );
        assert_eq!(
            firmware_release_contract_blocker(
                true,
                Some(0x1234_5678),
                false,
                1,
                Some(SBSDIO_HT_AVAIL_REQ)
            ),
            "chipclkcsr-ht-avail-missing"
        );
        assert_eq!(
            firmware_release_contract_blocker(
                true,
                Some(0x1234_5678),
                true,
                1,
                Some(SBSDIO_HT_AVAIL)
            ),
            "none"
        );
        assert_eq!(
            firmware_release_contract_next_step(
                true,
                Some(0x1234_5678),
                1,
                Some(SBSDIO_HT_AVAIL_REQ),
                "disabled-not-ready"
            ),
            "linux-capture-post-release-chipclkcsr"
        );
        assert_eq!(
            sdio_function_contract_state_label(
                Some(SDIO_FUNC_ENABLE_1 | SDIO_FUNC_ENABLE_2),
                Some(SDIO_FUNC_READY_1),
                SDIO_FUNC_ENABLE_2,
                SDIO_FUNC_READY_2,
            ),
            "enabled-not-ready"
        );
    }

    #[test]
    fn post_release_proof_labels_upload_and_nvram_tail_layout() {
        let ram_base = CYW43_RAM_BASE_4345;
        let ram_size = 0x1000;
        let firmware_len = 0x400;
        let nvram_offset = ram_base + 0x800;
        let nvram_len = 0x7fc;
        let nvram_tail = ram_base + ram_size - 4;

        assert_eq!(
            firmware_release_checked_end(ram_base, firmware_len),
            Some(ram_base + firmware_len as u32)
        );
        assert_eq!(
            firmware_release_upload_range_state(ram_base, ram_size, firmware_len, nvram_offset),
            "upload-range-ok"
        );
        assert_eq!(
            firmware_release_nvram_tail_state(
                ram_base,
                ram_size,
                nvram_offset,
                nvram_len,
                nvram_tail,
            ),
            "nvram-tail-ok"
        );
        assert_eq!(
            firmware_release_upload_range_state(ram_base, ram_size, 0x900, nvram_offset),
            "firmware-overlaps-nvram"
        );
        assert_eq!(
            firmware_release_nvram_tail_state(
                ram_base,
                ram_size,
                nvram_offset,
                nvram_len - 4,
                nvram_tail,
            ),
            "nvram-tail-gap"
        );
    }

    #[test]
    fn post_release_proof_labels_cpuhalt_and_sideband_state() {
        let release_ioctrl = armcr4_release_ioctrl_value();
        assert_eq!(release_ioctrl, AI_CORE_POSTRESET_IOCTRL);
        assert_eq!(
            firmware_cpuhalt_release_state(release_ioctrl, 0),
            "cpuhalt-clear-core-up"
        );
        assert_eq!(
            firmware_cpuhalt_release_state(release_ioctrl | ARMCR4_BCMA_IOCTL_CPUHALT, 0),
            "cpuhalt-still-set"
        );
        assert_eq!(
            firmware_cpuhalt_release_state(release_ioctrl, AI_RESETCTRL_BIT_RESET),
            "reset-still-held"
        );
        assert_eq!(
            firmware_reset_vector_state(0x1234_5678),
            "reset-vector-programmed"
        );
        assert_eq!(firmware_reset_vector_state(0), "zero-vector-linux-skip");
        assert_eq!(
            firmware_chipclkcsr_state(Some(SBSDIO_HT_AVAIL_REQ | SBSDIO_ALP_AVAIL)),
            "ht-requested-not-avail"
        );
        assert_eq!(
            firmware_chipclkcsr_state(Some(SBSDIO_HT_AVAIL_REQ | SBSDIO_HT_AVAIL)),
            "ht-avail"
        );
        assert_eq!(
            firmware_wakeupctrl_state(Some(SBSDIO_WAKE_TILL_HT_AVAIL)),
            "htwait-set"
        );
        assert_eq!(
            firmware_sleepcsr_state(Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK)),
            "kso-only"
        );
        assert_eq!(
            firmware_sleepcsr_state(Some(
                SBSDIO_FUNC1_SLEEPCSR_KSO_MASK | SBSDIO_FUNC1_SLEEPCSR_DEVON_MASK,
            )),
            "kso-devon"
        );
        assert_eq!(
            firmware_cardcap_state(Some(cyw43455_cardcap_command_decode_value())),
            "cmd14-decode-ok"
        );
        assert_eq!(
            firmware_release_precondition_state(
                "upload-range-ok",
                "nvram-tail-ok",
                "cpuhalt-clear-core-up",
                Some(SBSDIO_HT_AVAIL_REQ | SBSDIO_ALP_AVAIL),
            ),
            "chipclkcsr-ht-missing"
        );
        assert_eq!(
            firmware_release_precondition_state(
                "upload-range-ok",
                "nvram-tail-ok",
                "cpuhalt-clear-core-up",
                Some(SBSDIO_HT_AVAIL_REQ | SBSDIO_HT_AVAIL),
            ),
            "ready-for-function2-ht"
        );
    }

    #[test]
    fn sdio_transfer_plan_keeps_linux_byte_mode_for_aligned_firmware_write_below_byte_ceiling() {
        let write = sdio_transfer_plan(SdioFunction::Function1, 256, true)
            .expect("function1 bulk write transfer plan");
        assert_eq!(write.block_size, 256);
        assert_eq!(write.block_count, 1);
        assert_eq!(write.cmd53_count, 256);
        assert!(!write.block_mode);
        assert_ne!(write.transfer_mode & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_eq!(write.transfer_mode & SDHCI_TRNS_MULTI, 0);
        assert_eq!(write.transfer_mode & SDHCI_TRNS_READ, 0);
    }

    #[test]
    fn sdio_transfer_plan_keeps_linux_byte_mode_for_single_function_block_write() {
        let write = sdio_transfer_plan(SdioFunction::Function1, 64, true)
            .expect("function1 single-block write transfer plan");
        assert_eq!(write.block_size, 64);
        assert_eq!(write.block_count, 1);
        assert_eq!(write.cmd53_count, 64);
        assert!(!write.block_mode);
        assert_ne!(write.transfer_mode & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_eq!(write.transfer_mode & SDHCI_TRNS_MULTI, 0);
        assert_eq!(write.transfer_mode & SDHCI_TRNS_READ, 0);
    }

    #[test]
    fn sdio_transfer_plan_uses_block_mode_once_transfer_exceeds_linux_byte_ceiling() {
        let read = sdio_transfer_plan(SdioFunction::Function2, 1024, false)
            .expect("function2 block-mode transfer plan");
        assert_eq!(read.block_size, SDIO_FUNCTION_ENABLE_F2.block_size);
        assert_eq!(read.block_count, 2);
        assert_eq!(read.cmd53_count, 2);
        assert!(read.block_mode);
        assert_ne!(read.transfer_mode & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_ne!(read.transfer_mode & SDHCI_TRNS_MULTI, 0);
        assert_ne!(read.transfer_mode & SDHCI_TRNS_READ, 0);
    }

    #[test]
    fn experimental_function2_fifo_chunk_limit_splits_no_ht_fifo_reads_from_writes() {
        assert_eq!(
            experimental_function2_fifo_chunk_limit(SdioFunction::Function2, false, true, true),
            experimental_no_ht_f2_fifo_chunk_limit(true)
        );
        assert_eq!(
            experimental_function2_fifo_chunk_limit(SdioFunction::Function2, true, true, true),
            experimental_no_ht_f2_fifo_chunk_limit(true)
        );
        assert_eq!(
            experimental_no_ht_f2_fifo_chunk_limit(true),
            SDIO_FUNCTION_ENABLE_F2.block_size as usize
        );
        assert_eq!(
            experimental_function2_fifo_chunk_limit(SdioFunction::Function2, false, false, true),
            experimental_no_ht_f2_fifo_chunk_limit(false)
        );
        assert!(
            experimental_no_ht_f2_fifo_chunk_limit(false)
                < experimental_no_ht_f2_fifo_chunk_limit(true)
        );
        assert_eq!(
            experimental_function2_fifo_chunk_limit(SdioFunction::Function2, true, false, true),
            SDIO_MAX_BYTE_MODE
        );
        assert_eq!(
            experimental_function2_fifo_chunk_limit(SdioFunction::Function1, false, false, true),
            SDIO_MAX_BYTE_MODE
        );
        assert_eq!(
            experimental_function2_fifo_chunk_limit(SdioFunction::Function2, false, false, false),
            SDIO_MAX_BYTE_MODE
        );
    }

