    #[test]
    fn control_plane_snapshot_diag_labels_compactly_encode_state() {
        assert_eq!(
            control_plane_snapshot_bit_state_label(
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                SDIO_FUNCTION_ENABLE_F2.enable_bit
            ),
            "set"
        );
        assert_eq!(
            control_plane_snapshot_bit_state_label(Some(0), SDIO_FUNCTION_ENABLE_F2.enable_bit),
            "clear"
        );
        assert_eq!(
            control_plane_snapshot_bit_state_label(None, SDIO_FUNCTION_ENABLE_F2.enable_bit),
            "unread"
        );
        assert_eq!(
            control_plane_snapshot_match_label(Some(HOSTINTMASK), HOSTINTMASK),
            "match"
        );
        assert_eq!(
            control_plane_snapshot_match_label(Some(0), HOSTINTMASK),
            "diff"
        );
        assert_eq!(
            control_plane_snapshot_match_label(None, HOSTINTMASK),
            "unread"
        );
        assert_eq!(control_plane_snapshot_hint_visibility_label(0), "none");
        assert_eq!(control_plane_snapshot_hint_visibility_label(2), "part");
        assert_eq!(control_plane_snapshot_hint_visibility_label(4), "full");
        assert_eq!(
            control_plane_snapshot_reply_frame_label(Some(0), Some(0)),
            "seen"
        );
        assert_eq!(
            control_plane_snapshot_reply_frame_label(Some(0), None),
            "miss"
        );
        assert_eq!(
            control_plane_snapshot_exact_blocker_label(
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                Some(0),
                Some(SDIO_INTERRUPT_ENABLE_MASK),
                Some(CC_F2RDY),
                0,
                None,
                None,
                None,
                None,
                Some(CY_43455_F2_WATERMARK),
                Some(SBSDIO_DEVCTL_F2WM_ENAB),
                Some(CY_43455_MESBUSYCTRL),
            ),
            "f2-ready-hidden-from-cccr"
        );
        assert_eq!(
            control_plane_snapshot_exact_blocker_label(
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                Some(0),
                Some(SDIO_INTERRUPT_ENABLE_MASK),
                None,
                0,
                None,
                None,
                None,
                None,
                Some(CY_43455_F2_WATERMARK),
                Some(SBSDIO_DEVCTL_F2WM_ENAB),
                Some(CY_43455_MESBUSYCTRL),
            ),
            "sdio-core-hints-unreadable"
        );
        assert_eq!(
            control_plane_snapshot_exact_blocker_label(
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                Some(0),
                Some(SDIO_INTERRUPT_ENABLE_MASK),
                Some(0),
                4,
                Some(HOSTINTMASK),
                Some(FUNCTIONINTMASK),
                Some(0),
                Some(0),
                Some(CY_43455_F2_WATERMARK),
                Some(SBSDIO_DEVCTL_F2WM_ENAB),
                Some(CY_43455_MESBUSYCTRL),
            ),
            "f2-enable-latched-not-ready"
        );
        assert_eq!(
            control_plane_snapshot_exact_blocker_label(
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                Some(SDIO_INTERRUPT_ENABLE_MASK),
                None,
                0,
                None,
                None,
                None,
                None,
                Some(CY_43455_F2_WATERMARK),
                Some(SBSDIO_DEVCTL_F2WM_ENAB),
                Some(CY_43455_MESBUSYCTRL),
            ),
            "sdio-core-hints-unreadable"
        );
        assert_eq!(
            control_plane_snapshot_exact_blocker_label(
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                Some(SDIO_INTERRUPT_ENABLE_MASK),
                None,
                4,
                Some(HOSTINTMASK),
                Some(FUNCTIONINTMASK),
                Some(0),
                Some(0),
                Some(CY_43455_F2_WATERMARK),
                Some(SBSDIO_DEVCTL_F2WM_ENAB),
                Some(CY_43455_MESBUSYCTRL),
            ),
            "state-visible"
        );
        assert_eq!(
            control_plane_snapshot_exact_blocker_label(
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                Some(SDIO_FUNCTION_ENABLE_F2.enable_bit),
                Some(0),
                None,
                4,
                Some(HOSTINTMASK),
                Some(FUNCTIONINTMASK),
                Some(0),
                Some(0),
                Some(CY_43455_F2_WATERMARK),
                Some(SBSDIO_DEVCTL_F2WM_ENAB),
                Some(CY_43455_MESBUSYCTRL),
            ),
            "linux-configured-interrupts-deferred"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label("f2-ready-hidden-from-cccr"),
            "cyw43-function2-ready-hidden-from-cccr"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label("sdio-core-hints-unreadable"),
            "cyw43-control-plane-sideband-unreadable"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label_with_sdhci_diag(
                "sdio-core-hints-unreadable",
                "f1-reply-read-command-timeout",
            ),
            "cyw43-control-plane-sideband-command-timeout"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label_with_sdhci_diag(
                "sdio-core-hints-unreadable",
                "f1-reply-read-command-phase-no-data-active",
            ),
            "cyw43-control-plane-sideband-command-stall"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label_with_sdhci_diag(
                "sdio-core-hints-unreadable",
                "f1-reply-read-stalled-no-buffer-ready",
            ),
            "cyw43-control-plane-sideband-read-stall-no-buffer-ready"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label_with_sdhci_diag(
                "f2-enable-latched-not-ready",
                "f2-reply-read-command-timeout",
            ),
            "cyw43-function2-enable-latched-not-ready-command-timeout"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label_with_sdhci_diag(
                "f2-enable-latched-not-ready",
                "f2-reply-read-command-phase-no-data-active",
            ),
            "cyw43-function2-enable-latched-not-ready-command-stall"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label_with_sdhci_diag(
                "f2-enable-latched-not-ready",
                "f2-reply-read-data-end-bit",
            ),
            "cyw43-function2-enable-latched-not-ready-data-end-bit"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label_with_sdhci_diag(
                "f2-enable-latched-not-ready",
                "f2-reply-read-data-crc",
            ),
            "cyw43-function2-enable-latched-not-ready-data-crc"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label("reply-frame-missing"),
            "cyw43-control-plane-reply-frame-missing"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label("linux-configured-interrupts-deferred"),
            "cyw43-control-plane-linux-interrupts-deferred"
        );
        assert_eq!(
            control_plane_snapshot_exact_error_label("state-visible"),
            "cyw43-control-plane-state-visible-no-reply"
        );
    }

    #[test]
    fn control_plane_snapshot_sdhci_read_diag_identifies_stalled_f1_reply_reads() {
        let read_arg = (u32::from(SdioFunction::Function1.number()) << 28)
            | (sdio_core_byte_function_addr(SDPCMD_REG_TOHOSTMAILBOXDATA) << 9)
            | 4;
        assert_eq!(
            control_plane_snapshot_sdhci_read_diag_label(
                Some(SDIO_CMD53),
                Some(read_arg),
                Some(0),
                Some(SDHCI_INT_TIMEOUT),
            ),
            "f1-reply-read-command-timeout"
        );
        assert_eq!(
            control_plane_snapshot_sdhci_read_diag_label(
                Some(SDIO_CMD53),
                Some(read_arg),
                Some(SDHCI_DATA_INHIBIT | SDHCI_READ_TRANSFER_ACTIVE),
                Some(0),
            ),
            "f1-reply-read-command-phase-no-data-active"
        );
        assert_eq!(
            control_plane_snapshot_sdhci_read_diag_label(
                Some(SDIO_CMD53),
                Some(read_arg),
                Some(SDHCI_DATA_INHIBIT | SDHCI_DAT_ACTIVE | SDHCI_READ_TRANSFER_ACTIVE),
                Some(0),
            ),
            "f1-reply-read-stalled-no-buffer-ready"
        );
        let write_arg = read_arg | (1 << 31);
        assert_eq!(
            control_plane_snapshot_sdhci_read_diag_label(
                Some(SDIO_CMD53),
                Some(write_arg),
                Some(SDHCI_DATA_INHIBIT | SDHCI_DAT_ACTIVE | SDHCI_WRITE_TRANSFER_ACTIVE),
                Some(0),
            ),
            "none"
        );
    }

