    fn required_ht_wait_uses_linux_non_sr_clkavail_with_real_ht_gate() {
        assert!(required_ht_clock_uses_force_ht_timeout_retry());
        assert!(!required_ht_clock_linux_active_transition_uses_force_ht());
        assert!(required_ht_clock_linux_active_transition_resets_chipclk());
        assert!(
            required_ht_clock_linux_active_transition_resets_chipclk_for_stage("wait-ht-clock")
        );
        assert!(
            required_ht_clock_linux_active_transition_resets_chipclk_for_stage("debug-probe-ht")
        );
        assert!(
            required_ht_clock_linux_active_transition_resets_chipclk_for_attempt(
                "wait-ht-clock",
                false,
            )
        );
        assert!(
            !required_ht_clock_linux_active_transition_resets_chipclk_for_attempt(
                "wait-ht-clock",
                true,
            )
        );
        assert!(!cyw43455_uses_linux_sr_kso_clock());
        assert!(!required_ht_clock_uses_pre_function2_kso_gate());
        assert!(post_download_devon_before_ht_is_diagnostic());
        assert!(!post_download_ht_sleepcsr_uses_linux_clear_set());
        assert!(post_download_ht_sleepcsr_clear_set_is_nonterminal());
        assert!(!devon_before_ht_may_be_deferred_for_stage(
            "pre-write-alp-clock"
        ));
        assert!(!devon_before_ht_may_be_deferred_for_stage("wait-ht-clock"));
        assert!(sleepcsr_kso_acknowledged(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK));
        assert!(!sleepcsr_device_on_awake(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK));
        assert_eq!(required_ht_clock_request_value(None), SBSDIO_HT_AVAIL_REQ);
        assert_eq!(
            post_download_ht_sleepcsr_value(Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK)),
            SBSDIO_FUNC1_SLEEPCSR_KSO_MASK
        );
        assert_eq!(
            required_ht_clock_linux_active_wait_loops(),
            super::CYW43_HT_CLOCK_LINUX_ACTIVE_WAIT_LOOPS
        );
        assert_eq!(
            required_ht_clock_linux_active_wait_loops(),
            super::CYW43_HT_CLOCK_LINUX_ACTIVE_WAIT_POLLS
        );
        assert!(super::CYW43_HT_CLOCK_LINUX_ACTIVE_SETTLE_LOOPS > 0);
        assert!(
            super::CYW43_HT_CLOCK_LINUX_ACTIVE_WAIT_POLLS < super::CYW43_HT_CLOCK_SOFT_WAIT_LOOPS
        );
        assert!(super::CYW43_HT_CLOCK_LINUX_ACTIVE_WAIT_POLLS <= 200);
        assert!(
            super::CYW43_HT_CLOCK_LINUX_ACTIVE_SETTLE_LOOPS
                > super::SDIO_FUNCTION_READY_SETTLE_LOOPS
        );
        assert!(
            super::CYW43_HT_CLOCK_LINUX_SDONLY_SETTLE_LOOPS
                > super::CYW43_HT_CLOCK_LINUX_ACTIVE_SETTLE_LOOPS
        );
    }

    #[test]
    fn post_release_ht_transition_clears_observed_chipclk_before_request() {
        let observed_failure_shape = SBSDIO_HT_AVAIL_REQ | SBSDIO_ALP_AVAIL;

        assert_eq!(observed_failure_shape, 0x50);
        assert!(required_ht_clock_linux_active_transition_resets_chipclk());
        assert_eq!(
            required_ht_clock_request_value(Some(observed_failure_shape)),
            SBSDIO_HT_AVAIL_REQ
        );
        assert!(!function2_has_required_ht_clock(observed_failure_shape));
        assert_eq!(
            diagnostic_ht_clock_force_probe_value(Some(observed_failure_shape)),
            SBSDIO_HT_AVAIL_REQ
        );
        assert_eq!(
            required_ht_clock_retry_request_value(Some(observed_failure_shape)),
            SBSDIO_HT_AVAIL_REQ | SBSDIO_FORCE_HT
        );
        assert_eq!(
            function2_force_ht_clock_value(observed_failure_shape),
            SBSDIO_HT_AVAIL_REQ | SBSDIO_FORCE_HT
        );
    }

    #[test]
    fn forced_alp_kso_tuple_can_try_f2_ready_even_on_effective_startup_clock() {
        let forced_tuple = SBSDIO_HT_AVAIL_REQ | SBSDIO_FORCE_HT | SBSDIO_ALP_AVAIL;
        let wake = Some(SBSDIO_WAKE_TILL_HT_AVAIL);
        let sleep = Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK);
        let cardcap = Some(cyw43455_cardcap_command_decode_value());

        assert!(function2_forced_ht_clock_can_try_ready_poll(
            CYW43_STARTUP_CLOCK_HZ.saturating_sub(1)
        ));
        assert!(function2_accepts_linux_alp_kso_forced_ht_clock(
            false,
            forced_tuple,
            wake,
            sleep,
            cardcap,
            CYW43_STARTUP_CLOCK_HZ.saturating_sub(1),
        ));
        assert_eq!(
            function2_ready_phase_chipclk_value(Some(forced_tuple)),
            SBSDIO_HT_AVAIL_REQ | SBSDIO_FORCE_HT
        );
    }

    #[test]
    fn forced_alp_kso_cutover_accepts_reported_pi4_snapshot_without_cardcap() {
        let forced_tuple = SBSDIO_HT_AVAIL_REQ | SBSDIO_FORCE_HT | SBSDIO_ALP_AVAIL;
        let wake = Some(SBSDIO_WAKE_TILL_HT_AVAIL);
        let sleep = Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK);

        assert_eq!(forced_tuple, 0x52);
        assert_eq!(wake, Some(0x02));
        assert_eq!(sleep, Some(0x01));
        assert!(!post_download_ht_sideband_shadow_is_complete(
            wake, sleep, None
        ));
        assert!(post_download_forced_alp_kso_sideband_allows_function2_probe(wake, sleep, None));
        assert!(post_download_forced_alp_kso_sideband_allows_function2_probe(wake, sleep, Some(0)));
        assert!(function2_accepts_linux_alp_kso_forced_ht_clock(
            false,
            forced_tuple,
            wake,
            sleep,
            None,
            CYW43_STARTUP_CLOCK_HZ,
        ));
        assert!(function2_accepts_linux_alp_kso_forced_ht_clock(
            false,
            forced_tuple,
            wake,
            sleep,
            Some(0),
            CYW43_STARTUP_CLOCK_HZ,
        ));
        assert!(!function2_accepts_linux_alp_kso_forced_ht_clock(
            false,
            SBSDIO_HT_AVAIL_REQ | SBSDIO_ALP_AVAIL,
            wake,
            sleep,
            None,
            CYW43_STARTUP_CLOCK_HZ,
        ));
        assert!(!function2_accepts_linux_alp_kso_forced_ht_clock(
            false,
            forced_tuple,
            None,
            sleep,
            None,
            CYW43_STARTUP_CLOCK_HZ,
        ));
        assert!(!function2_accepts_linux_alp_kso_forced_ht_clock(
            false,
            forced_tuple,
            wake,
            Some(0),
            None,
            CYW43_STARTUP_CLOCK_HZ,
        ));
    }

    #[test]
    fn firmware_readback_status_is_explicit_and_bounded() {
        assert!(!firmware_download_readback_verify_required(false));
        assert_eq!(
            firmware_download_readback_status(false, false),
            "linux-debug-readback-skipped"
        );
        assert_eq!(
            firmware_download_readback_status(true, false),
            "required-readback-not-verified"
        );
        assert_eq!(
            firmware_download_readback_status(true, true),
            "verified-bounded-readback"
        );
        assert_eq!(CYW43_FIRMWARE_PROOF_CHUNK, 64);
        assert!(CYW43_FIRMWARE_PROOF_CHUNK < CYW43_FIRMWARE_VERIFY_CHUNK);
    }

