        assert!(!backplane_sdio_pullup_clear_enabled());
        assert!(!backplane_sdio_pullup_clear_width_allowed(
            SdioBusWidth::OneBit
        ));
        assert!(backplane_sdio_pullup_clear_width_allowed(
            SdioBusWidth::FourBit
        ));
