    #[test]
    fn next_distinct_firmware_bulk_clock_candidate_skips_duplicates() {
        let unique_restore = firmware_bulk_clock_candidates(400_000, true);
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&unique_restore, 0),
            Some(CYW43_FIRMWARE_BULK_CLOCK_HZ / 2)
        );
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&unique_restore, 1),
            Some(CYW43_FIRMWARE_BULK_CLOCK_HZ / 4)
        );
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&unique_restore, 2),
            Some(400_000)
        );
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&unique_restore, 3),
            None
        );

        let duplicate_restore =
            firmware_bulk_clock_candidates(CYW43_FIRMWARE_BULK_CLOCK_HZ / 2, true);
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&duplicate_restore, 0),
            Some(CYW43_FIRMWARE_BULK_CLOCK_HZ / 2)
        );
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&duplicate_restore, 1),
            Some(CYW43_FIRMWARE_BULK_CLOCK_HZ / 4)
        );
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&duplicate_restore, 2),
            None
        );

        let pre_ht_restore = firmware_bulk_clock_candidates(400_000, false);
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&pre_ht_restore, 0),
            Some(800_000)
        );
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&pre_ht_restore, 1),
            Some(400_000)
        );
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&pre_ht_restore, 2),
            None
        );
        assert_eq!(
            next_distinct_firmware_bulk_clock_candidate(&pre_ht_restore, 3),
            None
        );
    }

    #[test]
    fn ht_clock_assist_constants_match_broadcom_sequence() {
        assert_eq!(SBSDIO_FORCE_HT, 0x02);
        assert_eq!(SBSDIO_WAKE_TILL_HT_AVAIL, 0x02);
        assert_eq!(SDIO_CCCR_BRCM_CARDCAP_CMD14_SUPPORT, 0x02);
        assert_eq!(SDIO_CCCR_BRCM_CARDCAP_CMD14_EXT, 0x04);
        assert_eq!(SDIO_CCCR_BRCM_CARDCAP_CMD_NODEC, 0x08);
        assert_eq!(cyw43455_cardcap_command_decode_value(), 0x06);
        assert!(!pre_function2_ht_sideband_programs_sr_registers());
        assert!(post_download_ht_request_primes_wake_sideband());
        assert!(post_download_ht_stage_primes_wake_sideband("wait-ht-clock"));
        assert!(post_download_ht_stage_primes_wake_sideband(
            "post-function2-sr-init"
        ));
        assert!(!post_download_ht_sleepcsr_uses_linux_clear_set());
        assert!(post_download_ht_sleepcsr_clear_set_is_nonterminal());
        assert_eq!(
            post_download_ht_wakeupctrl_value(None),
            SBSDIO_WAKE_TILL_HT_AVAIL
        );
        assert_eq!(
            post_download_ht_wakeupctrl_value(Some(0x80)),
            0x80 | SBSDIO_WAKE_TILL_HT_AVAIL
        );
        assert_eq!(post_download_ht_cardcap_value(), 0x06);
        assert_eq!(
            post_download_ht_sleepcsr_value(None),
            SBSDIO_FUNC1_SLEEPCSR_KSO_MASK
        );
        assert_eq!(
            post_download_ht_sleepcsr_value(Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK)),
            SBSDIO_FUNC1_SLEEPCSR_KSO_MASK
        );
        assert_eq!(
            post_download_ht_sleepcsr_value(Some(
                SBSDIO_FUNC1_SLEEPCSR_KSO_MASK | SBSDIO_FUNC1_SLEEPCSR_DEVON_MASK | 0x80
            )),
            SBSDIO_FUNC1_SLEEPCSR_KSO_MASK | SBSDIO_FUNC1_SLEEPCSR_DEVON_MASK
        );
        assert_eq!(
            cyw43455_cardcap_command_decode_value() & SDIO_CCCR_BRCM_CARDCAP_CMD_NODEC,
            0
        );
    }

    #[test]
    fn linux_probe_attach_registers_match_brcmfmac_broadcom_order() {
        assert_eq!(super::SDIO_CCCR_BRCM_CARDCTRL, 0xF1);
        assert_eq!(super::SDIO_CCCR_BRCM_CARDCTRL_WLANRESET, 0x02);
        assert_eq!(super::chipcommon_pmucontrol_addr(), 0x1800_0600);
        assert_eq!(super::CHIPCOMMON_PMUCONTROL_RES_RELOAD_VALUE, 0x2);
        assert_eq!(super::CHIPCOMMON_PMUCONTROL_RES_SHIFT, 13);
        assert_eq!(super::chipcommon_pmucontrol_res_reload_bits(), 0x4000);
        assert_eq!(super::CYW43_D11_CORE_BASES, [0x1810_1000]);
        assert_eq!(super::D11_BCMA_IOCTL_PHYCLOCKEN, 0x04);
        assert_eq!(super::D11_BCMA_IOCTL_PHYRESET, 0x08);
        assert!(super::core_ctrl_can_defer_in_reset_readback(
            super::CYW43_D11_CORE_BASES[0],
            true,
            false,
        ));
        assert!(!super::linux_probe_attach_uses_live_pmu_readback());
        assert!(!super::linux_probe_attach_uses_live_iorx_readback());
    }

    #[test]
    fn ht_clock_assist_shadow_refresh_requires_cached_registers() {
        assert!(ht_clock_assist_shadow_is_complete(
            Some(0x02),
            Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK | SBSDIO_FUNC1_SLEEPCSR_DEVON_MASK),
            Some(cyw43455_cardcap_command_decode_value()),
        ));
        assert!(!ht_clock_assist_shadow_is_complete(
            None,
            Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK | SBSDIO_FUNC1_SLEEPCSR_DEVON_MASK),
            Some(cyw43455_cardcap_command_decode_value())
        ));
        assert!(!ht_clock_assist_shadow_is_complete(
            Some(0x02),
            None,
            Some(cyw43455_cardcap_command_decode_value())
        ));
        assert!(!ht_clock_assist_shadow_is_complete(
            Some(0x02),
            Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK | SBSDIO_FUNC1_SLEEPCSR_DEVON_MASK),
            None,
        ));
        assert!(!ht_clock_assist_shadow_is_complete(
            Some(0),
            Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK),
            Some(cyw43455_cardcap_command_decode_value()),
        ));
        assert!(!ht_clock_assist_shadow_is_complete(
            Some(0x02),
            Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK),
            Some(cyw43455_cardcap_command_decode_value()),
        ));
        assert!(ht_clock_assist_shadow_is_complete(
            Some(0x02),
            Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK | SBSDIO_FUNC1_SLEEPCSR_DEVON_MASK),
            Some(cyw43455_cardcap_command_decode_value()),
        ));
        assert!(!ht_clock_assist_shadow_is_complete(
            Some(0x02),
            Some(0),
            Some(cyw43455_cardcap_command_decode_value()),
        ));
        assert!(post_download_ht_sideband_shadow_is_complete(
            Some(SBSDIO_WAKE_TILL_HT_AVAIL),
            Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK),
            Some(cyw43455_cardcap_command_decode_value()),
        ));
    }

    #[test]
    fn post_download_ht_sideband_prime_accepts_only_forced_pi4_edge_for_function2() {
        let wake = Some(SBSDIO_WAKE_TILL_HT_AVAIL);
        let sleep = Some(SBSDIO_FUNC1_SLEEPCSR_KSO_MASK);
        let cardcap = Some(cyw43455_cardcap_command_decode_value());
        let production_timeout = SBSDIO_HT_AVAIL_REQ | SBSDIO_ALP_AVAIL;
        let diagnostic_timeout = SBSDIO_HT_AVAIL_REQ | SBSDIO_FORCE_HT | SBSDIO_ALP_AVAIL;

        assert!(post_download_ht_sideband_shadow_is_complete(
            wake, sleep, cardcap
        ));
        assert!(!function2_has_required_ht_clock(production_timeout));
        assert!(!function2_has_required_ht_clock(diagnostic_timeout));
        assert!(!function2_accepts_linux_alp_kso_forced_ht_clock(
            false,
            production_timeout,
            wake,
            sleep,
            cardcap,
            CYW43_FIRMWARE_BULK_CLOCK_HZ / 4,
        ));
        assert!(function2_accepts_linux_alp_kso_forced_ht_clock(
            false,
            diagnostic_timeout,
            wake,
            sleep,
            cardcap,
            CYW43_FIRMWARE_BULK_CLOCK_HZ / 4,
        ));
    }

